 */
function getValueQ(): string {
  const storedValue = window.localStorage.getItem('VALUEQ');
  const parsedValue = storedValue ? JSON.parse(storedValue) : true;
  return parsedValue;
}

/**
 *
 */
function getValueE(): string {
  const storedValue = window.localStorage.getItem('VALUEE');
  const parsedValue = storedValue ? JSON.parse(storedValue) : true;
  return parsedValue;
}

const state = reactive({
  valueE: ref(JSON.parse(getValueE())),
  valueQ: ref(JSON.parse(getValueQ())),
});
/* eslint @typescript-eslint/no-explicit-any: "off" */
/* eslint @typescript-eslint/explicit-module-boundary-types: "off" */
/**
 *
 * @param value
 */
function setValueQ(value: any): void {
  state.valueQ = value;
  window.localStorage.setItem('VALUEQ', JSON.stringify(value));
}

/**
 *
 * @param value
 */
function setValueE(value: any): void {
  state.valueE = value;
  window.localStorage.setItem('VALUEE', JSON.stringify(value));
}

// Export necessary functions and data
export { state, setValueQ, setValueE, getValueQ, getValueE };

const USER_ID_KEY = 'userId';

export const getUserId = (): number | undefined => {
  const userId = localStorage.getItem(USER_ID_KEY);
  return userId ? Number.parseInt(userId, 10) : undefined;
};

export const setUserId = (userId: number): void => {
  localStorage.setItem(USER_ID_KEY, userId.toString());
};

import { createI18n } from 'vue-i18n';
import ar from './locales/ar.json';
import cz from './locales/cz.json';
import en from './locales/en.json';
import es from './locales/es-ES.json';
import esMX from './locales/es-MX.json';
import fr from './locales/fr.json';
import pl from './locales/pl.json';
import ptBR from './locales/pt-BR.json';
import pt from './locales/pt-PT.json';
import sk from './locales/sk.json';
import zh from './locales/zh-CN.json';
import zhHK from './locales/zh-HK.json';

export const supportedLocales = [
  'ar',
  'cz',
  'en',
  'es-es',
  'es-mx',
  'fr',
  'pl',
  'pt-pt',
  'pt-br',
  'sk',
  'zh-cn',
  'zh-hk',
] as const;

export type SupportedLocale = (typeof supportedLocales)[number];

const messages = Object.fromEntries([
  ['ar', ar],
  ['cz', cz],
  ['en', en],
  ['es-es', es],
  ['es-mx', esMX],
  ['fr', fr],
  ['pl', pl],
  ['pt-br', ptBR],
  ['pt-pt', pt],
  ['sk', sk],
  ['zh-cn', zh],
  ['zh-hk', zhHK],
]) as unknown as Record<SupportedLocale, Record<string, string>>;

/**
 * Export a global i18n instance that can be used by stores and non-setup code.
 * Import { i18n } and use i18n.global.t(...) when outside of a component setup.
 */
export const i18n = createI18n({
  fallbackLocale: 'en',
  globalInjection: true,
  legacy: false,
  locale: 'en',
  messages,
});

/**
 * Returns the shared i18n instance used to initialize the app.
 * @returns The shared Vue i18n instance.
 */
export async function setupI18n(): Promise<typeof i18n> {
  return i18n;
}

import mainHeader, { NotifyPlugin } from '@mesx/common-ui-lib';
import elementPlus from 'element-plus';
import { createPinia } from 'pinia';
import piniaPluginPersistedstate from 'pinia-plugin-persistedstate';
import { Quasar, Notify, Loading } from 'quasar';
import { createApp } from 'vue';
import App from './App.vue';
import { router } from './global-router/index.ts';
import { i18n } from './localization/i18n.ts';
import 'element-plus/dist/index.css';
import '@mesx/common-ui-lib/style.css';
import '@quasar/extras/material-symbols-outlined/material-symbols-outlined.css';
import '@quasar/extras/material-symbols-rounded/material-symbols-rounded.css';
import './styles/tailwind.css';
import './modules/page-builder/styles/pb-theme.css';
/**
 * Initializes the application by setting up necessary configurations, services, or data.
 * This function is typically called when the app starts.
 * @returns A promise that resolves when the initialization is complete.
 */
async function initializeApp(): Promise<void> {
  const pinia = createPinia();
  const app = createApp(App);
  app.use(Quasar, {
    plugins: { Notify, Loading },
  });
  const { $q } = app.config.globalProperties;
  app.use(NotifyPlugin, { $q });
  app.use(elementPlus);
  app.use(pinia);
  pinia.use(piniaPluginPersistedstate);
  app.use(router);
  // Use the shared i18n instance (synchronous)
  app.use(i18n);
  app.use(mainHeader);
  app.mount('#app');
}
initializeApp();

