export type UpdateKitmatSkipLevelRequestDTO = UpdateBOMComponentsRequestDTO;
export type UpdateKitmatSkipLevelResponseDTO = UpdateBOMComponentsResponseDTO;

import axios, { AxiosResponse } from 'axios';
import {
  BOMResponseDTO,
  GetBOMQueryParametersDTO,
  UpdateBOMComponentsRequestDTO,
  UpdateBOMComponentsResponseDTO,
  BOMListItemDTO,
