const adminUrl = import.meta.env.ADMIN_BACKEND_URL;
const umeApiUrl =
  import.meta.env.UME_API_URL ?? import.meta.env.URL_UME_BACKEND;

/**
 * Resolves and normalizes a required backend base URL.
 * @param name Environment variable name used in the error message.
 * @param value Raw environment value to validate.
 * @returns Normalized base URL without trailing slashes.
 */
function getBaseUrl(name: string, value: string | undefined): string {
  const normalizedValue = value?.trim();

  if (!normalizedValue) {
    throw new Error(`${name} is not configured.`);
  }

  return normalizedValue.replace(/\/+$/, '');
}

/**
 * Resolves the access token used for authenticated NPS API requests.
 * @returns Bearer token value or an empty string when no token is available.
 */
function getAccessToken(): string {
  const configuredToken = import.meta.env.TOKEN ?? '';

  if (configuredToken === 'PING_FEDERATE') {
    return sessionStorage.getItem('id_token') ?? '';
  }

  return configuredToken;
}

/**
 * Builds the request headers for authenticated API calls.
 * @returns Header map for the current request context.
 */
function getHeaders(): Record<string, string> {
  const token = getAccessToken();

  if (!token) {
    return {};
  }

  return {
    authorization: `Bearer ${token}`,
  };
}

/**
 * Executes a typed GET request against the NPS backend.
 * @param url Fully qualified endpoint URL.
 * @returns Parsed response payload.
 */
async function getRequest<T>(url: string): Promise<T> {
  const response: AxiosResponse<T> = await axios.get(url, {
    headers: getHeaders(),
  });

  return response.data;
}

export class NpsApiService {
  public static async listConfigurations(): Promise<
    Array<NpsApiConfiguration>
  > {
    return getRequest<Array<NpsApiConfiguration>>(
      `${getBaseUrl('ADMIN_BACKEND_URL', adminUrl)}/nps-config/get-nps-list`,
    );
  }

  public static async getConfiguration(
    npsId: number,
  ): Promise<NpsApiConfiguration> {
    return getRequest<NpsApiConfiguration>(
      `${getBaseUrl('ADMIN_BACKEND_URL', adminUrl)}/nps-config/get-nps-by-id/${encodeURIComponent(String(npsId))}`,
    );
  }

  public static async getConfigRoles(
    npsId: number,
  ): Promise<Array<NpsApiRoleAssignment>> {
    return getRequest<Array<NpsApiRoleAssignment>>(
      `${getBaseUrl('ADMIN_BACKEND_URL', adminUrl)}/nps-config-role/get-role-by-nps/${encodeURIComponent(String(npsId))}`,
    );
  }

  public static async getRolesByAppName(
    appName: string,
  ): Promise<Array<NpsRoleOption>> {
    return getRequest<Array<NpsRoleOption>>(
      `${getBaseUrl('ADMIN_BACKEND_URL', adminUrl)}/permission/get-role-by-app-name/${encodeURIComponent(appName)}`,
    );
  }

  public static async getScoreSummary(npsId: number): Promise<NpsScoreSummary> {
    return getRequest<NpsScoreSummary>(
      `${getBaseUrl('ADMIN_BACKEND_URL', adminUrl)}/nps-response/score/by-config/${encodeURIComponent(String(npsId))}`,
    );
  }

  public static async getResponses(
    npsId: number,
  ): Promise<Array<Omit<NpsResponseRecord, 'id'>>> {
    return getRequest<Array<Omit<NpsResponseRecord, 'id'>>>(
      `${getBaseUrl('UME_API_URL', umeApiUrl)}/nps-response/by-config/${encodeURIComponent(String(npsId))}`,
    );
  }

  public static async updateConfiguration(
    npsId: number,
    payload: NpsUpdatePayload,
  ): Promise<void> {
    const headers = {
      ...getHeaders(),
    };

    headers['Content-Type'] = 'application/json';

    await axios.put(
      `${getBaseUrl('ADMIN_BACKEND_URL', adminUrl)}/nps-config/update-nps/${encodeURIComponent(String(npsId))}`,
      payload,
      {
        headers,
      },
    );
  }
}

import { defineStore } from 'pinia';
import { computed, ref } from 'vue';
import { NpsApiService } from '../services/nps.api';
import type {
  NpsApiConfiguration,
  NpsApiNumericValue,
  NpsApiRoleAssignment,
  NpsConfigurationForm,
  NpsDismissalBehavior,
  NpsResponseRecord,
  NpsRoleOption,
  NpsScreenRecord,
  NpsScoreSummary,
  NpsTriggerType,
} from '../types/nps.types';
import { i18n } from '@/localization/i18n';

/**
 * Translates an NPS localization key with optional interpolation values.
 * @param key Localization key to resolve.
 * @param values Optional interpolation values for the message.
 * @returns Localized string value.
 */
function translate(key: string, values?: Record<string, unknown>): string {
  return String(i18n.global.t(key, values ?? {}));
}

/**
 * Normalizes unknown errors to a user-facing backend error message.
 * @param error Unknown thrown value.
 * @returns Safe error message for the UI.
 */
function getErrorMessage(error: unknown): string {
  if (error instanceof Error && error.message.trim().length > 0) {
    return error.message;
  }

  return translate('NPS_BACKEND_ERROR');
}

/**
 * Trims an application name value while tolerating missing backend data.
 * @param appName Raw application name from the API.
 * @returns Trimmed application name or an empty string.
 */
function normalizeAppName(appName: string | null | undefined): string {
  return (appName ?? '').trim();
}

/**
 * Trims optional backend text values.
 * @param value Raw text value from the API.
 * @returns Trimmed text or an empty string.
 */
function normalizeText(value: string | null | undefined): string {
  return (value ?? '').trim();
}

/**
 * Formats a technical application name into a readable label.
 * @param appName Raw application name from the API.
 * @returns Human-readable application name.
 */
function formatAppName(appName: string | null | undefined): string {
  const normalizedValue = normalizeAppName(appName);

  if (normalizedValue.length === 0) {
    return '';
  }

  return normalizedValue
    .split(/[-_\s]+/u)
    .filter((segment) => segment.length > 0)
    .map((segment) => {
      const lowerCasedSegment = segment.toLowerCase();

      return `${lowerCasedSegment.charAt(0).toUpperCase()}${lowerCasedSegment.slice(1)}`;
    })
    .join(' ');
}

/**
 * Parses numeric API values into a finite score.
 * @param value Raw API score value.
 * @returns Parsed score or undefined when the value is empty or invalid.
 */
function parseScoreNumber(
  value: NpsApiNumericValue | undefined,
): number | undefined {
  if (value === null || value === undefined || value === '') {
    return undefined;
  }

  const parsedValue =
    typeof value === 'number' ? value : Number.parseFloat(String(value));

  return Number.isFinite(parsedValue) ? parsedValue : undefined;
}

/**
 * Parses the numeric configuration identifier from a screen id.
 * @param screenId Screen identifier stored in the UI.
 * @returns Numeric NPS id or undefined when parsing fails.
 */
function parseNpsId(screenId: string): number | undefined {
  const parsedValue = Number.parseInt(screenId, 10);

  return Number.isNaN(parsedValue) ? undefined : parsedValue;
}

/**
 * Parses non-negative integer values from the API.
 * @param value Raw numeric value from the backend.
 * @returns Parsed non-negative number or undefined when invalid.
 */
function parsePositiveNumber(
  value: NpsApiNumericValue | undefined,
): number | undefined {
  if (value === null || value === undefined || value === '') {
    return undefined;
  }

  const parsedValue =
    typeof value === 'number' ? value : Number.parseInt(String(value), 10);

  if (Number.isNaN(parsedValue) || parsedValue < 0) {
    return undefined;
  }

  return parsedValue;
}

/**
 * Parses and validates a role identifier.
 * @param value Raw role id value.
 * @returns Parsed role id or undefined when invalid.
 */
function parseRoleId(value: number | string): number | undefined {
  const parsedValue =
    typeof value === 'number' ? value : Number.parseInt(value, 10);

  if (Number.isNaN(parsedValue) || parsedValue < 0) {
    return undefined;
  }

  return parsedValue;
}

/**
 * Normalizes backend trigger types to the supported UI enum.
 * @param value Raw trigger type from the backend.
 * @returns Supported trigger type.
 */
function parseTriggerType(value: string | null | undefined): NpsTriggerType {
  if (value === 'EVENT_BASED' || value === 'MANUAL') {
    return value;
  }

  return 'TIME_BASED';
}

/**
 * Checks whether the response type represents a submitted score.
 * @param value Raw response type value.
 * @returns True when the response was submitted.
 */
function isSubmittedResponseType(value: string | null | undefined): boolean {
  return value?.trim().toUpperCase() === 'SUBMITTED';
}

/**
 * Counts responses that contributed a submitted score.
 * @param responses Loaded response records.
 * @returns Number of submitted responses.
 */
function countSubmittedResponses(responses: Array<NpsResponseRecord>): number {
  return responses.filter((response) =>
    isSubmittedResponseType(response.responseType),
  ).length;
}

/**
 * Resolves the dismissal behavior from API dismissal fields.
 * @param value Raw dismissal value from the API.
 * @param repromptDay Optional reprompt day count that implies day-based behavior.
 * @returns Normalized dismissal behavior.
 */
function parseDismissalBehavior(
  value: NpsApiNumericValue | undefined,
  repromptDay: NpsApiNumericValue | undefined,
): NpsDismissalBehavior {
  if (typeof value === 'string') {
    const normalizedValue = value.trim().toUpperCase();

    if (normalizedValue === 'NEVER_REPROMPT') {
      return 'NEVER_REPROMPT';
    }

    if (normalizedValue === 'REPROMPT_AFTER_DAYS') {
      return 'REPROMPT_AFTER_DAYS';
    }

    if (normalizedValue === 'NO_SHOW_UNTIL_RELOAD') {
      return 'NO_SHOW_UNTIL_RELOAD';
    }
  }

  if ((parsePositiveNumber(repromptDay) ?? 0) > 0) {
    return 'REPROMPT_AFTER_DAYS';
  }

  const parsedValue = parsePositiveNumber(value);

  if (parsedValue === 2) {
    return 'NEVER_REPROMPT';
  }

  if (parsedValue === 1) {
    return 'REPROMPT_AFTER_DAYS';
  }

  return 'NO_SHOW_UNTIL_RELOAD';
}

/**
 * Deduplicates role options by numeric role id.
 * @param roleOptions Raw role options from the API.
 * @returns Unique role options with normalized ids.
 */
function dedupeRoles(roleOptions: Array<NpsRoleOption>): Array<NpsRoleOption> {
  const seenRoleIds = new Set<number>();

  return roleOptions.flatMap((role) => {
    const normalizedRoleId = parseRoleId(role.roleId);

    if (normalizedRoleId === undefined || seenRoleIds.has(normalizedRoleId)) {
      return [];
    }

    seenRoleIds.add(normalizedRoleId);

    return [
      {
        roleId: normalizedRoleId,
        roleName: role.roleName,
      },
    ];
  });
}

/**
 * Normalizes role names for case-insensitive comparison.
 * @param roleName Raw role name.
 * @returns Lower-cased role name.
 */
function normalizeRoleName(roleName: string | null | undefined): string {
  return (roleName ?? '').trim().toLowerCase();
}

/**
 * Parses the comma-separated configured role names from the backend.
 * @param roleNames Raw comma-separated role name list.
 * @returns Normalized configured role names.
 */
function parseConfiguredRoleNames(
  roleNames: string | null | undefined,
): Array<string> {
  return (
    roleNames
      ?.split(',')
      .map((roleName) => normalizeRoleName(roleName))
      .filter((roleName) => roleName.length > 0) ?? []
  );
}

/**
 * Parses a configured array of role names from the backend.
 * @param roleNames Raw configured role names.
 * @returns Normalized role name list.
 */
function parseConfiguredRoleNameList(
  roleNames: Array<string> | null | undefined,
): Array<string> {
  return (
    roleNames
      ?.map((roleName) => normalizeRoleName(roleName))
      .filter((roleName) => roleName.length > 0) ?? []
  );
}

/**
 * Resolves the effective role ids assigned to a configuration.
 * @param configuration Backend configuration record.
 * @param roleAssignments Saved role assignments for the configuration.
 * @param roleOptions Available application role options.
 * @returns Effective assigned role ids.
 */
function resolveAssignedRoleIds(
  configuration: NpsApiConfiguration,
  roleAssignments: Array<NpsApiRoleAssignment>,
  roleOptions: Array<NpsRoleOption>,
): Array<number> {
  const assignedRoleIds = new Set(roleAssignments.map((role) => role.roleId));
  const configuredRoleNames = new Set([
    ...parseConfiguredRoleNames(configuration.roleName),
    ...parseConfiguredRoleNameList(configuration.roleNames),
  ]);

  if (configuredRoleNames.size === 0) {
    return [...assignedRoleIds];
  }

  for (const role of [...roleOptions, ...roleAssignments]) {
    if (configuredRoleNames.has(normalizeRoleName(role.roleName))) {
      assignedRoleIds.add(role.roleId);
    }
  }

  return [...assignedRoleIds];
}

/**
 * Creates the card description shown in the NPS overview.
 * @param displayName Fallback screen display name.
 * @param appTitle Optional application title from the backend.
 * @returns Card description text.
 */
function createCardDescription(
  displayName: string,
  appTitle: string | null | undefined,
): string {
  const normalizedAppTitle = normalizeText(appTitle);
  const baseTitle =
    normalizedAppTitle.length > 0 ? normalizedAppTitle : displayName;

  if (baseTitle.length > 0) {
    return `MES X.0 ${baseTitle} Screen NPS`;
  }

  return '';
}

/**
 * Computes the overview sort rank for a screen record.
 * @param screen Screen record to rank.
 * @returns Sort rank where lower values are shown first.
 */
function getScreenOrderRank(screen: NpsScreenRecord): number {
  const hasResponses = screen.responseCount > 0;

  if (screen.status === 'ACTIVE' && hasResponses) {
    return 0;
  }

  if (screen.status === 'ACTIVE') {
    return 1;
  }

  if (hasResponses) {
    return 2;
  }

  return 3;
}

/**
 * Normalizes role assignments to valid numeric role ids.
 * @param roleAssignments Raw role assignments from the backend.
 * @returns Role assignments with normalized ids.
 */
function normalizeRoleAssignments(
  roleAssignments: Array<NpsApiRoleAssignment>,
): Array<NpsApiRoleAssignment> {
  const normalizedRoleAssignments: Array<NpsApiRoleAssignment> = [];

  for (const role of roleAssignments) {
    const normalizedRoleId = parseRoleId(role.roleId);

    if (normalizedRoleId !== undefined) {
      normalizedRoleAssignments.push({
        ...role,
        roleId: normalizedRoleId,
      });
    }
  }

  return normalizedRoleAssignments;
}

/**
 * Normalizes role options to valid numeric role ids.
 * @param roleOptions Raw role options from the backend.
 * @returns Role options with normalized ids.
 */
function normalizeRoleOptions(
  roleOptions: Array<NpsRoleOption>,
): Array<NpsRoleOption> {
  const normalizedRoleOptions: Array<NpsRoleOption> = [];

  for (const role of roleOptions) {
    const normalizedRoleId = parseRoleId(role.roleId);

    if (normalizedRoleId !== undefined) {
      normalizedRoleOptions.push({
        roleId: normalizedRoleId,
        roleName: role.roleName,
      });
    }
  }

  return normalizedRoleOptions;
}

/**
 * Creates an initial score summary from configuration-level API fields.
 * @param configuration Backend configuration record.
 * @returns Derived score summary.
 */
function createScoreSummaryFromConfiguration(
  configuration: NpsApiConfiguration,
): NpsScoreSummary {
  const npsScore = parseScoreNumber(configuration.npsScore) ?? 0;
  const totalResponses = parsePositiveNumber(configuration.totalResponses) ?? 0;

  return {
    detractors: 0,
    npsScore,
    passives: 0,
    promoters: 0,
    totalResponses,
  };
}

/**
 * Maps an API configuration to the editable form used by the store.
 * @param configuration Backend configuration record.
 * @param roleIds Allowed role ids for the configuration.
 * @returns Editable configuration form.
 */
function toConfigurationForm(
  configuration: NpsApiConfiguration,
  roleIds: Array<number>,
): NpsConfigurationForm {
  const redisplayDays = parsePositiveNumber(configuration.redisplayInterval);
  const appName = formatAppName(configuration.appName);
  const triggerType = parseTriggerType(configuration.triggerType);
  const lastResponseType = configuration.responseType ?? undefined;
  const isManualTrigger = triggerType === 'MANUAL';

  return {
    allowedRoleIds: [...roleIds],
    allowedShift: ['ALL'],
    appName,
    behaviorOnDismissal: isManualTrigger
      ? 'NO_SHOW_UNTIL_RELOAD'
      : parseDismissalBehavior(
          configuration.behaviorDismissal,
          configuration.repromptDay,
        ),
    customRedisplayDays: redisplayDays ?? undefined,
    isActive: configuration.isActive,
    isCommentRequired: configuration.commentRequired,
    lastResponseType,
    lastUpdated: configuration.updatedAt ?? undefined,
    npsId: configuration.npsId,
    rawBehaviorDismissal: isManualTrigger
      ? null
      : (configuration.behaviorDismissal ?? undefined),
    redisplayInterval: redisplayDays === undefined ? 'NEVER' : 'CUSTOM',
    releaseVersion: configuration.releaseId ?? '',
    repromptDay: isManualTrigger
      ? undefined
      : (parsePositiveNumber(configuration.repromptDay) ?? undefined),
    showFloatingButton: isManualTrigger
      ? !isSubmittedResponseType(lastResponseType)
      : configuration.showButton,
    triggerDelaySeconds:
      parsePositiveNumber(configuration.triggerDelayTime) ?? undefined,
    triggerEventKey:
      configuration.eventName ?? configuration.apiUrlPattern ?? undefined,
    triggerType,
  };
}

/**
 * Creates the store record for a single NPS screen.
 * @param configuration Backend configuration record.
 * @param scoreSummary Aggregated score summary for the screen.
 * @param roleIds Effective allowed role ids.
 * @param responses Loaded screen responses.
 * @returns Normalized screen record for the store.
 */
function createScreenRecord(
  configuration: NpsApiConfiguration,
  scoreSummary: NpsScoreSummary,
  roleIds: Array<number>,
  responses: Array<NpsResponseRecord>,
): NpsScreenRecord {
  const displayName =
    normalizeText(configuration.appTitle) ||
    formatAppName(configuration.appName);
  const description = createCardDescription(
    displayName,
    configuration.appTitle,
  );

  return {
    configuration: toConfigurationForm(configuration, roleIds),
    description,
    id: String(configuration.npsId),
    name: displayName,
    responseCount:
      responses.length > 0
        ? countSubmittedResponses(responses)
        : Number(scoreSummary.totalResponses ?? 0),
    responses,
    score: Math.round(Number(scoreSummary.npsScore ?? 0)),
    status: configuration.isActive ? 'ACTIVE' : 'INACTIVE',
  };
}

/**
 * Merges a refreshed screen record into the current screen list.
 * @param existingScreens Current store screen records.
 * @param nextScreen Updated screen record.
 * @returns Screen list containing the updated record.
 */
function mergeScreen(
  existingScreens: Array<NpsScreenRecord>,
  nextScreen: NpsScreenRecord,
): Array<NpsScreenRecord> {
  const existingIndex = existingScreens.findIndex(
    (screen) => screen.id === nextScreen.id,
  );

  if (existingIndex === -1) {
    return [...existingScreens, nextScreen];
  }

  return existingScreens.map((screen) =>
    screen.id === nextScreen.id ? nextScreen : screen,
  );
}

export const useNpsStore = defineStore('npsStore', () => {
  const screens = ref<Array<NpsScreenRecord>>([]);
  const availableRoles = ref<Array<NpsRoleOption>>([]);
  const isLoadingResponses = ref(false);
  const isLoadingScreens = ref(false);
  const isLoadingSelectedScreen = ref(false);
  const isSavingConfiguration = ref(false);
  const screensError = ref<string>();
  const selectedScreenError = ref<string>();
  const selectedScreenId = ref('');
  const screensLoaded = ref(false);
  const configurationCache = new Map<number, NpsApiConfiguration>();
  const scoreSummaryCache = new Map<number, NpsScoreSummary>();
  const roleAssignmentsCache = new Map<number, Array<NpsApiRoleAssignment>>();
  const roleOptionsCache = new Map<string, Array<NpsRoleOption>>();
  const configurationRequestCache = new Map<
    number,
    Promise<NpsApiConfiguration>
  >();
  const scoreSummaryRequestCache = new Map<number, Promise<NpsScoreSummary>>();
  const roleAssignmentsRequestCache = new Map<
    number,
    Promise<Array<NpsApiRoleAssignment>>
  >();
  const roleOptionsRequestCache = new Map<
    string,
    Promise<Array<NpsRoleOption>>
  >();

  const selectedScreen = computed(() =>
    screens.value.find((screen) => screen.id === selectedScreenId.value),
  );
  const visibleScreens = computed(() => screens.value);

  /**
   * Stores the currently selected screen id.
   * @param screenId Screen identifier to mark as selected.
   */
  function setSelectedScreen(screenId: string): void {
    selectedScreenId.value = screenId;
  }

  /**
   * Inserts or replaces a screen record in the store.
   * @param screen Screen record to upsert.
   */
  function upsertScreen(screen: NpsScreenRecord): void {
    screens.value = mergeScreen(screens.value, screen);
  }

  /**
   * Clears cached overview data so it can be reloaded from the backend.
   */
  function clearOverviewCaches(): void {
    configurationCache.clear();
    scoreSummaryCache.clear();
    configurationRequestCache.clear();
    scoreSummaryRequestCache.clear();
  }

  /**
   * Invalidates all cached data for a specific configuration id.
   * @param npsId NPS configuration id to clear.
   */
  function invalidateScreenCache(npsId: number): void {
    configurationCache.delete(npsId);
    scoreSummaryCache.delete(npsId);
    roleAssignmentsCache.delete(npsId);
    configurationRequestCache.delete(npsId);
    scoreSummaryRequestCache.delete(npsId);
    roleAssignmentsRequestCache.delete(npsId);
  }

  /**
   * Returns a cached configuration request or loads a fresh configuration.
   * @param npsId NPS configuration id to load.
   * @param force When true, bypasses the cache and reloads from the backend.
   * @returns Configuration promise for the requested id.
   */
  function getCachedConfiguration(
    npsId: number,
    force = false,
  ): Promise<NpsApiConfiguration> {
    if (!force) {
      const cachedConfiguration = configurationCache.get(npsId);

      if (cachedConfiguration) {
        return Promise.resolve(cachedConfiguration);
      }

      const cachedRequest = configurationRequestCache.get(npsId);

      if (cachedRequest) {
        return cachedRequest;
      }
    }

    const request = NpsApiService.getConfiguration(npsId)
      .then((configuration) => {
        configurationCache.set(npsId, configuration);
        configurationRequestCache.delete(npsId);
        return configuration;
      })
      .catch((error: unknown) => {
        configurationRequestCache.delete(npsId);
        throw error;
      });

    configurationRequestCache.set(npsId, request);
    return request;
  }

  /**
   * Returns a cached score summary or loads it from the backend.
   * @param npsId NPS configuration id to load.
   * @param force When true, bypasses the cache and reloads from the backend.
   * @returns Score summary promise for the requested id.
   */
  function getCachedScoreSummary(
    npsId: number,
    force = false,
  ): Promise<NpsScoreSummary> {
    if (!force) {
      const cachedScoreSummary = scoreSummaryCache.get(npsId);

      if (cachedScoreSummary) {
        return Promise.resolve(cachedScoreSummary);
      }

      const cachedRequest = scoreSummaryRequestCache.get(npsId);

      if (cachedRequest) {
        return cachedRequest;
      }
    }

    const request = NpsApiService.getScoreSummary(npsId)
      .then((scoreSummary) => {
        scoreSummaryCache.set(npsId, scoreSummary);
        scoreSummaryRequestCache.delete(npsId);
        return scoreSummary;
      })
      .catch((error: unknown) => {
        scoreSummaryRequestCache.delete(npsId);
        throw error;
      });

    scoreSummaryRequestCache.set(npsId, request);
    return request;
  }

  /**
   * Returns cached role assignments or loads them from the backend.
   * @param npsId NPS configuration id to load.
   * @param force When true, bypasses the cache and reloads from the backend.
   * @returns Role assignment promise for the requested id.
   */
  function getCachedRoleAssignments(
    npsId: number,
    force = false,
  ): Promise<Array<NpsApiRoleAssignment>> {
    if (!force) {
      const cachedRoleAssignments = roleAssignmentsCache.get(npsId);

      if (cachedRoleAssignments) {
        return Promise.resolve(cachedRoleAssignments);
      }

      const cachedRequest = roleAssignmentsRequestCache.get(npsId);

      if (cachedRequest) {
        return cachedRequest;
      }
    }

    const request = NpsApiService.getConfigRoles(npsId)
      .then((roleAssignments) => {
        const normalizedRoleAssignments =
          normalizeRoleAssignments(roleAssignments);

        roleAssignmentsCache.set(npsId, normalizedRoleAssignments);
        roleAssignmentsRequestCache.delete(npsId);
        return normalizedRoleAssignments;
      })
      .catch((error: unknown) => {
        roleAssignmentsRequestCache.delete(npsId);
        throw error;
      });

    roleAssignmentsRequestCache.set(npsId, request);
    return request;
  }

  /**
   * Returns cached application role options or loads them from the backend.
   * @param appName Application name used to load role options.
   * @param force When true, bypasses the cache and reloads from the backend.
   * @returns Role option promise for the requested application.
   */
  function getCachedRoleOptions(
    appName: string,
    force = false,
  ): Promise<Array<NpsRoleOption>> {
    if (appName.length === 0) {
      return Promise.resolve([]);
    }

    if (!force) {
      const cachedRoleOptions = roleOptionsCache.get(appName);

      if (cachedRoleOptions) {
        return Promise.resolve(cachedRoleOptions);
      }

      const cachedRequest = roleOptionsRequestCache.get(appName);

      if (cachedRequest) {
        return cachedRequest;
      }
    }

    const request = NpsApiService.getRolesByAppName(appName)
      .then((roleOptions) => {
        const normalizedRoleOptions = normalizeRoleOptions(roleOptions);

        roleOptionsCache.set(appName, normalizedRoleOptions);
        roleOptionsRequestCache.delete(appName);
        return normalizedRoleOptions;
      })
      .catch((error: unknown) => {
        roleOptionsRequestCache.delete(appName);
        throw error;
      });

    roleOptionsRequestCache.set(appName, request);
    return request;
  }

  /**
   * Loads responses from the backend.
   * @param npsId NPS configuration id to load.
   * @param screenId Screen identifier used to build stable response ids.
   * @returns Response list promise for the requested screen.
   */
  function getCachedResponses(
    npsId: number,
    screenId: string,
  ): Promise<Array<NpsResponseRecord>> {
    const responses = NpsApiService.getResponses(npsId).then((result) =>
      result.map((response, index) => ({
        ...response,
        id: `${screenId}-${index}`,
      })),
    );
    return responses;
  }

  /**
   * Loads the NPS overview screen list.
   * @param force When true, reloads screens even if they were loaded before.
   * @returns Promise that resolves when the overview data is ready.
   */
  async function loadScreens(force = false): Promise<void> {
    if (isLoadingScreens.value || (!force && screensLoaded.value)) {
      return;
    }

    isLoadingScreens.value = true;
    screensError.value = undefined;

    try {
      if (force) {
        clearOverviewCaches();
      }

      const configurations = await NpsApiService.listConfigurations();
      const nextScreens = configurations.map((configuration) => {
        configurationCache.set(configuration.npsId, configuration);

        const scoreSummary = createScoreSummaryFromConfiguration(configuration);

        scoreSummaryCache.set(configuration.npsId, scoreSummary);

        return createScreenRecord(configuration, scoreSummary, [], []);
      });

      nextScreens.sort((left, right) => {
        const rankDifference =
          getScreenOrderRank(left) - getScreenOrderRank(right);

        if (rankDifference !== 0) {
          return rankDifference;
        }

        if (left.responseCount !== right.responseCount) {
          return right.responseCount - left.responseCount;
        }

        return left.name.localeCompare(right.name);
      });

      if (nextScreens.length === 0 && configurations.length > 0) {
        throw new Error(translate('NPS_BACKEND_ERROR'));
      }

      screens.value = nextScreens;
      screensLoaded.value = true;

      if (!selectedScreenId.value && nextScreens[0]) {
        selectedScreenId.value = nextScreens[0].id;
      }
    } catch (error) {
      screens.value = [];
      screensError.value = getErrorMessage(error);
      screensLoaded.value = false;
    } finally {
      isLoadingScreens.value = false;
    }
  }

  /**
   * Loads the selected screen details and refreshes its cached data.
   * @param screenId Screen identifier to load.
   * @param force When true, bypasses cached screen data.
   * @returns Loaded screen record or undefined when the id is invalid or the load fails.
   */
  async function loadSelectedScreen(
    screenId: string,
    force = false,
  ): Promise<NpsScreenRecord | undefined> {
    const npsId = parseNpsId(screenId);

    if (npsId === undefined) {
      selectedScreenError.value = getErrorMessage(
        new Error(translate('NPS_BACKEND_ERROR')),
      );
      return undefined;
    }

    setSelectedScreen(screenId);
    isLoadingSelectedScreen.value = true;
    selectedScreenError.value = undefined;

    try {
      const existingScreen = screens.value.find(
        (screen) => screen.id === screenId,
      );
      const configuration = await getCachedConfiguration(npsId, force);
      const normalizedAppName = normalizeAppName(configuration.appName);
      const [scoreSummary, roleAssignments, roleOptions] = await Promise.all([
        getCachedScoreSummary(npsId, force),
        getCachedRoleAssignments(npsId, force),
        getCachedRoleOptions(normalizedAppName, force),
      ]);
      const assignedRoleIds = resolveAssignedRoleIds(
        configuration,
        roleAssignments,
        roleOptions,
      );
      const nextScreen = createScreenRecord(
        configuration,
        scoreSummary,
        assignedRoleIds,
        existingScreen?.responses ?? [],
      );

      upsertScreen(nextScreen);
      availableRoles.value = dedupeRoles([
        ...roleOptions,
        ...roleAssignments.map((role) => ({
          roleId: role.roleId,
          roleName: role.roleName,
        })),
      ]);

      return nextScreen;
    } catch (error) {
      selectedScreenError.value = getErrorMessage(error);
      return undefined;
    } finally {
      isLoadingSelectedScreen.value = false;
    }
  }

  /**
   * Persists configuration changes for a given screen.
   * @param screenId Screen identifier to update.
   * @param configuration Next configuration form values.
   */
  async function saveConfiguration(
    screenId: string,
    configuration: NpsConfigurationForm,
  ): Promise<void> {
    const npsId = parseNpsId(screenId);

    if (npsId === undefined) {
      throw new Error(translate('NPS_BACKEND_ERROR'));
    }

    isSavingConfiguration.value = true;
    selectedScreenError.value = undefined;

    try {
      invalidateScreenCache(npsId);
      const isManualTrigger = configuration.triggerType === 'MANUAL';
      let repromptDay: number | null | undefined;
      let triggerDelayTime: number | null | undefined;

      if (isManualTrigger) {
        repromptDay = null;
      } else if (configuration.behaviorOnDismissal === 'REPROMPT_AFTER_DAYS') {
        repromptDay = Math.max(configuration.repromptDay ?? 1, 1);
      } else {
        repromptDay = undefined;
      }

      if (isManualTrigger) {
        triggerDelayTime = null;
      } else if (configuration.triggerType === 'TIME_BASED') {
        triggerDelayTime = Math.max(configuration.triggerDelaySeconds ?? 5, 5);
      } else {
        triggerDelayTime = undefined;
      }

      await NpsApiService.updateConfiguration(npsId, {
        behaviorDismissal: isManualTrigger
          ? null
          : configuration.behaviorOnDismissal,
        commentRequired: configuration.isCommentRequired,
        isActive: configuration.isActive,
        redisplayInterval:
          configuration.redisplayInterval === 'CUSTOM'
            ? Math.max(configuration.customRedisplayDays ?? 1, 1)
            : 0,
        repromptDay,
        roleIds: configuration.allowedRoleIds,
        showButton: isManualTrigger
          ? !isSubmittedResponseType(configuration.lastResponseType)
          : configuration.showFloatingButton,
        triggerDelayTime,
        triggerType: configuration.triggerType,
      });

      await loadSelectedScreen(screenId, true);
    } catch (error) {
      selectedScreenError.value = getErrorMessage(error);
      throw error;
    } finally {
      isSavingConfiguration.value = false;
    }
  }

  /**
   * Reloads the current configuration from the backend and returns the fresh form.
   * @param screenId Screen identifier to refresh.
   * @returns Refreshed configuration form or undefined when the screen cannot be loaded.
   */
  async function resetConfiguration(
    screenId: string,
  ): Promise<NpsConfigurationForm | undefined> {
    const refreshedScreen = await loadSelectedScreen(screenId);

    return refreshedScreen?.configuration;
  }

  /**
   * Loads responses for the selected screen and updates the screen record.
   * @param screenId Screen identifier to load.
   * @returns Loaded response records.
   */
  async function loadResponses(
    screenId: string,
  ): Promise<Array<NpsResponseRecord>> {
    const npsId = parseNpsId(screenId);

    if (npsId === undefined) {
      return [];
    }

    isLoadingResponses.value = true;

    try {
      const mappedResponses = await getCachedResponses(npsId, screenId);
      const existingScreen = screens.value.find(
        (screen) => screen.id === screenId,
      );

      if (existingScreen) {
        upsertScreen({
          ...existingScreen,
          responseCount: countSubmittedResponses(mappedResponses),
          responses: mappedResponses,
        });
      }

      return mappedResponses;
    } finally {
      isLoadingResponses.value = false;
    }
  }

  return {
    availableRoles,
    isLoadingResponses,
    isLoadingScreens,
    isLoadingSelectedScreen,
    isSavingConfiguration,
    loadResponses,
    loadScreens,
    loadSelectedScreen,
    resetConfiguration,
    saveConfiguration,
    screens,
    screensError,
    selectedScreen,
    selectedScreenError,
    selectedScreenId,
    setSelectedScreen,
    visibleScreens,
  };
});

