type ReplaceAllFunction = (
  this: string,
  searchValue: string | RegExp,
  replaceValue: string,
) => string;

const stringReplaceAll = (
  String.prototype as unknown as {
    replaceAll: ReplaceAllFunction;
  }
).replaceAll;

/**
 * Applies String#replaceAll via the runtime prototype while keeping compatibility with the project's TS lib target.
 * @param value Source string.
 * @param searchValue Substring or global regular expression to replace.
 * @param replaceValue Replacement text.
 * @returns Updated string value.
 */
function callReplaceAll(
  value: string,
  searchValue: string | RegExp,
  replaceValue: string,
): string {
  return stringReplaceAll.call(value, searchValue, replaceValue);
}

/**
 * Escapes literal double quotes for Excel formula string fragments.
 * @param value Raw string value.
 * @returns Excel-safe string fragment.
 */
function escapeFormulaString(value: string): string {
  return callReplaceAll(value, '"', '""');
}

/**
 * Applies a solid fill color to a worksheet cell.
 * @param cell Target worksheet cell.
 * @param fillColor ARGB fill color.
 */
function applyFill(cell: Cell, fillColor: string): void {
  const targetCell = cell;

  targetCell.fill = {
    fgColor: { argb: fillColor },
    pattern: 'solid',
    type: 'pattern',
  };
}

/**
 * Converts a 1-based column number to its Excel column name.
 * @param columnNumber Worksheet column number.
 * @returns Excel column name.
 */
function columnNumberToName(columnNumber: number): string {
  let currentValue = columnNumber;
  let columnName = '';

  while (currentValue > 0) {
    const remainder = (currentValue - 1) % 26;

    columnName = String.fromCodePoint(65 + remainder) + columnName;
    currentValue = Math.floor((currentValue - 1) / 26);
  }

  return columnName;
}

/**
 * Builds an Excel cell address from column and row numbers.
 * @param columnNumber Worksheet column number.
 * @param rowNumber Worksheet row number.
 * @returns A1-style cell address.
 */
function getCellAddress(columnNumber: number, rowNumber: number): string {
  return `${columnNumberToName(columnNumber)}${rowNumber}`;
}

/**
 * Creates a uniform border configuration for a range.
 * @param color Border color in ARGB format.
 * @param style Border style.
 * @returns Uniform border object.
 */
function createUniformBorder(
  color: string,
  style: BorderStyle = 'thin',
): Partial<Borders> {
  return {
    bottom: { color: { argb: color }, style },
    left: { color: { argb: color }, style },
    right: { color: { argb: color }, style },
    top: { color: { argb: color }, style },
  };
}

/**
 * Applies fill and borders to a rectangular worksheet area.
 * @param worksheet Target worksheet.
 * @param startColumnNumber Starting column number.
 * @param endColumnNumber Ending column number.
 * @param startRowNumber Starting row number.
 * @param endRowNumber Ending row number.
 * @param fillColor Fill color in ARGB format.
 * @param border Border definition to apply.
 */
function styleArea(
  worksheet: Worksheet,
  startColumnNumber: number,
  endColumnNumber: number,
  startRowNumber: number,
  endRowNumber: number,
  fillColor: string,
  border: Partial<Borders> = LIGHT_BORDER,
): void {
  for (
    let rowNumber = startRowNumber;
    rowNumber <= endRowNumber;
    rowNumber += 1
  ) {
    for (
      let columnNumber = startColumnNumber;
      columnNumber <= endColumnNumber;
      columnNumber += 1
    ) {
      const cell = worksheet.getCell(getCellAddress(columnNumber, rowNumber));

      applyFill(cell, fillColor);
      cell.border = border;
    }
  }
}

/**
 * Merges a rectangular area and assigns its top-left cell value.
 * @param worksheet Target worksheet.
 * @param startColumnNumber Starting column number.
 * @param endColumnNumber Ending column number.
 * @param startRowNumber Starting row number.
 * @param endRowNumber Ending row number.
 * @param value Cell value to assign.
 * @returns Top-left merged cell.
 */
function setMergedCell(
  worksheet: Worksheet,
  startColumnNumber: number,
  endColumnNumber: number,
  startRowNumber: number,
  endRowNumber: number,
  value: Cell['value'],
): Cell {
  const range = `${getCellAddress(startColumnNumber, startRowNumber)}:${getCellAddress(
    endColumnNumber,
    endRowNumber,
  )}`;

  worksheet.mergeCells(range);

  const cell = worksheet.getCell(
    getCellAddress(startColumnNumber, startRowNumber),
  );

  cell.value = value;

  return cell;
}

/**
 * Applies a percentage data bar conditional formatting rule.
 * @param worksheet Target worksheet.
 * @param cellAddress Cell address to format.
 * @param accentColor Data bar color in ARGB format.
 * @param priority Conditional formatting priority.
 */
function applyPercentageDataBar(
  worksheet: Worksheet,
  cellAddress: string,
  accentColor: string,
  priority: number,
): void {
  const rule = {
    axisPosition: 'none',
    border: false,
    cfvo: [
      { type: 'num', value: 0 },
      { type: 'num', value: 1 },
    ],
    color: { argb: accentColor },
    direction: 'leftToRight',
    gradient: false,
    maxLength: 100,
    minLength: 0,
    priority,
    showValue: true,
    type: 'dataBar',
  };

  worksheet.addConditionalFormatting({
    ref: cellAddress,
    rules: [
      rule as unknown as Parameters<
        Worksheet['addConditionalFormatting']
      >[0]['rules'][0],
    ],
  });
}

/**
 * Returns the formula used to resolve the summary status icon from helper cells.
 * @returns Excel formula for the status icon.
 */
function createStatusIconFormula(): string {
  return 'IF($Y$9>=70,"☆",IF($Y$9>=30,"👍",IF($Y$9>=0,"☺","☹")))';
}

/**
 * Renders the summary sheet header section.
 * @param worksheet Target summary worksheet.
 * @param labels Localized export labels.
 * @param screenName Screen display name.
 * @param computedValues Precomputed summary values.
 */
function renderSummaryHeader(
  worksheet: Worksheet,
  labels: NpsExcelExportLabels,
  screenName: string,
  computedValues: SummaryComputedValues,
): void {
  styleArea(
    worksheet,
    1,
    13,
    1,
    1,
    SECTION_HEADER_FILL,
    createUniformBorder(SECTION_HEADER_FILL),
  );
  styleArea(worksheet, 15, 23, 1, 1, SECTION_SURFACE_FILL, LIGHT_BORDER);

  const titleCell = setMergedCell(
    worksheet,
    1,
    13,
    1,
    1,
    `${screenName} - ${labels.summaryTitle}`,
  );

  titleCell.font = { bold: true, color: { argb: TITLE_TEXT_COLOR }, size: 14 };
  titleCell.alignment = {
    horizontal: 'left',
    vertical: 'middle',
    wrapText: true,
  };

  const averageLabelCell = setMergedCell(
    worksheet,
    15,
    17,
    1,
    1,
    labels.averageScore,
  );
  averageLabelCell.font = {
    bold: true,
    color: { argb: SUBTLE_TEXT_COLOR },
    size: 10,
  };
  averageLabelCell.alignment = { horizontal: 'right', vertical: 'middle' };

  const averageValueCell = setMergedCell(worksheet, 18, 19, 1, 1, {
    formula: 'Y10',
    result: computedValues.averageScore,
  });
  averageValueCell.font = {
    bold: true,
    color: { argb: TITLE_TEXT_COLOR },
    size: 12,
  };
  averageValueCell.alignment = { horizontal: 'left', vertical: 'middle' };
  averageValueCell.numFmt = '0.0';

  const finalLabelCell = setMergedCell(
    worksheet,
    20,
    21,
    1,
    1,
    labels.finalScore,
  );
  finalLabelCell.font = {
    bold: true,
    color: { argb: SUBTLE_TEXT_COLOR },
    size: 10,
  };
  finalLabelCell.alignment = { horizontal: 'right', vertical: 'middle' };

  const finalValueCell = setMergedCell(worksheet, 22, 23, 1, 1, {
    formula: 'Y9',
    result: computedValues.npsScore,
  });
  finalValueCell.font = {
    bold: true,
    color: { argb: TITLE_TEXT_COLOR },
    size: 12,
  };
  finalValueCell.alignment = { horizontal: 'left', vertical: 'middle' };
  finalValueCell.numFmt = '0';
}

/**
 * Populates hidden helper cells used by summary formulas and charts.
 * @param worksheet Target summary worksheet.
 * @param labels Localized export labels.
 * @param summaryStatistics Summary statistics for the workbook.
 * @param computedValues Precomputed summary values.
 */
function populateSummaryHelperCells(
  worksheet: Worksheet,
  labels: NpsExcelExportLabels,
  summaryStatistics: SummaryStatistics,
  computedValues: SummaryComputedValues,
): void {
  const targetWorksheet = worksheet;

  targetWorksheet.getCell('Y2').value = summaryStatistics.totalResponses;
  targetWorksheet.getCell('Y3').value = computedValues.promotersSummary.share;
  targetWorksheet.getCell('Y4').value = computedValues.passivesSummary.share;
  targetWorksheet.getCell('Y5').value = computedValues.detractorsSummary.share;
  targetWorksheet.getCell('Y6').value = computedValues.promotersSummary.count;
  targetWorksheet.getCell('Y7').value = computedValues.passivesSummary.count;
  targetWorksheet.getCell('Y8').value = computedValues.detractorsSummary.count;
  targetWorksheet.getCell('Y9').value = computedValues.npsScore;
  targetWorksheet.getCell('Y10').value = computedValues.averageScore;
  targetWorksheet.getCell('Y11').value = computedValues.statusTitle;
  targetWorksheet.getCell('Y12').value = computedValues.statusDescription;
  targetWorksheet.getCell('X15').value = labels.score;
  targetWorksheet.getCell('Y15').value = labels.category;
  targetWorksheet.getCell('Z15').value = labels.count;
  targetWorksheet.getCell('AA15').value = labels.share;

  for (const [
    index,
    distributionRow,
  ] of summaryStatistics.distribution.entries()) {
    const rowNumber = SUMMARY_LAYOUT.distributionDataStartRow + index;

    targetWorksheet.getCell(`X${rowNumber}`).value = distributionRow.score;
    targetWorksheet.getCell(`Y${rowNumber}`).value = distributionRow.category;
    targetWorksheet.getCell(`Z${rowNumber}`).value = distributionRow.count;
    targetWorksheet.getCell(`AA${rowNumber}`).value = distributionRow.share;
  }
}

/**
 * Renders a single promoter/passive/detractor summary card.
 * @param worksheet Target summary worksheet.
 * @param config Card layout and content configuration.
 */
function renderSummaryMetricCard(
  worksheet: Worksheet,
  config: NpsSummaryMetricCardConfig,
): void {
  const titleCell = setMergedCell(
    worksheet,
    config.titleRange[0],
    config.titleRange[1],
    config.titleRange[2],
    config.titleRange[3],
