/**
 * Converts a readonly coordinate range into a mutable tuple.
 * @param range Readonly coordinate tuple.
 * @returns Mutable coordinate tuple.
 */
function toMutableRange(
  range: readonly [number, number, number, number],
): [number, number, number, number] {
  return [...range] as [number, number, number, number];
}

