import type { Workbook, Worksheet } from 'exceljs';
import type {
  NpsExcelExportLabels,
  SummaryComputedValues,
  SummaryStatistics,
  SummaryStatusStyle,
} from '../types/nps-export.types';
import { renderSummarySheetContent } from './nps-excel-export-summary-renderers';

const DETRACTOR_ACCENT = 'FFF04438';
const DETRACTORS_FILL = 'FFFFEEF1';
const STATUS_GOOD_FILL = 'FFFFF4D6';
const STATUS_GREAT_FILL = 'FFE7F0FB';

/**
 * Creates a valid Excel worksheet name with the workbook length limit applied.
 * @param baseName Requested worksheet name.
 * @param fallbackName Fallback worksheet name when the requested value is empty.
 * @returns Worksheet name truncated to Excel's maximum length.
 */
function createWorksheetName(baseName: string, fallbackName: string): string {
  const normalizedName = baseName.trim() || fallbackName;

  return normalizedName.slice(0, 31);
}

/**
 * Resolves the summary status styling for an NPS score.
 * @param npsScore Computed NPS score.
 * @returns Status style metadata.
 */
function resolveSummaryStatusStyle(npsScore: number): SummaryStatusStyle {
  if (npsScore >= 70) {
    return {
      accentColor: 'FF12B76A',
      borderColor: 'FF12B76A',
      fillColor: 'FFF0FDF4',
      key: 'excellent',
    };
  }

  if (npsScore >= 30) {
    return {
      accentColor: 'FF3B82F6',
      borderColor: 'FF60A5FA',
      fillColor: STATUS_GREAT_FILL,
      key: 'great',
    };
  }

  if (npsScore >= 0) {
    return {
      accentColor: 'FFF4B400',
      borderColor: 'FFF4B400',
      fillColor: STATUS_GOOD_FILL,
      key: 'good',
    };
  }

  return {
    accentColor: DETRACTOR_ACCENT,
    borderColor: 'FFEF4444',
    fillColor: DETRACTORS_FILL,
    key: 'needsWork',
  };
}

/**
 * Resolves the localized summary status title.
 * @param labels Localized export labels.
 * @param key Summary status key.
 * @returns Localized status title.
 */
function resolveStatusTitleText(
  labels: NpsExcelExportLabels,
  key: SummaryStatusStyle['key'],
): string {
  switch (key) {
    case 'excellent': {
      return labels.statusExcellent;
    }
    case 'great': {
      return labels.statusGreat;
    }
    case 'good': {
      return labels.statusGood;
    }
    default: {
      return labels.statusNeedsWork;
    }
  }
}

/**
 * Resolves the localized summary status description.
 * @param labels Localized export labels.
 * @param key Summary status key.
 * @returns Localized status description.
 */
function resolveStatusDescriptionText(
  labels: NpsExcelExportLabels,
  key: SummaryStatusStyle['key'],
): string {
  switch (key) {
    case 'excellent': {
      return labels.interpretationExcellent;
    }
    case 'great': {
      return labels.interpretationGreat;
    }
    case 'good': {
      return labels.interpretationGood;
    }
    default: {
      return labels.interpretationNeedsWork;
    }
  }
}

/**
 * Resolves the emoji icon shown for the current summary status.
 * @param key Summary status key.
 * @returns Emoji icon for the status.
 */
function resolveStatusIconText(key: SummaryStatusStyle['key']): string {
  switch (key) {
    case 'excellent': {
      return '☆';
    }
    case 'great': {
      return '👍';
    }
    case 'good': {
      return '☺';
    }
    default: {
      return '☹';
    }
  }
}

/**
 * Resolves the font family used for emoji status icons.
 * @returns Font family name for status icons.
 */
function resolveStatusIconFont(): string {
  return 'Segoe UI Emoji';
}

/**
 * Computes the derived summary values used by formulas and cards.
 * @param labels Localized export labels.
 * @param summaryStatistics Summary statistics for the workbook.
 * @returns Derived summary values for the summary sheet.
 */
function buildSummaryComputedValues(
  labels: NpsExcelExportLabels,
  summaryStatistics: SummaryStatistics,
): SummaryComputedValues {
  const detractorsSummary = summaryStatistics.categoryMix[0];
  const passivesSummary = summaryStatistics.categoryMix[1];
  const promotersSummary = summaryStatistics.categoryMix[2];
  let weightedScoreTotal = 0;

  for (const item of summaryStatistics.distribution) {
    weightedScoreTotal += item.score * item.count;
  }

  const averageScore =
    summaryStatistics.totalResponses === 0
      ? 0
      : weightedScoreTotal / summaryStatistics.totalResponses;
  const npsScore = Math.round(
    (promotersSummary.share - detractorsSummary.share) * 100,
  );
  const statusStyle = resolveSummaryStatusStyle(npsScore);

  return {
    averageScore,
    detractorsSummary,
    npsScore,
    passivesSummary,
    promotersSummary,
    statusDescription: resolveStatusDescriptionText(labels, statusStyle.key),
    statusIcon: resolveStatusIconText(statusStyle.key),
    statusIconFont: resolveStatusIconFont(),
    statusStyle,
    statusTitle: resolveStatusTitleText(labels, statusStyle.key),
  };
}

/**
 * Applies the standard summary-sheet row sizing and visibility rules.
 * @param worksheet Target summary worksheet.
 */
function configureSummaryWorksheetRows(worksheet: Worksheet): void {
  const targetWorksheet = worksheet;

  for (let rowNumber = 1; rowNumber <= 34; rowNumber += 1) {
    targetWorksheet.getRow(rowNumber).height = 24;
  }
  targetWorksheet.getRow(1).height = 30;
  targetWorksheet.getRow(2).height = 0;
  targetWorksheet.getRow(2).hidden = true;
  targetWorksheet.getRow(3).height = 0;
  targetWorksheet.getRow(3).hidden = true;
  targetWorksheet.getRow(4).height = 28;
  targetWorksheet.getRow(5).height = 24;
  targetWorksheet.getRow(6).height = 22;
  targetWorksheet.getRow(7).height = 20;
  targetWorksheet.getRow(9).height = 24;
  targetWorksheet.getRow(10).height = 24;
  targetWorksheet.getRow(11).height = 24;
  targetWorksheet.getRow(12).height = 24;
  targetWorksheet.getRow(13).height = 24;
  targetWorksheet.getRow(14).height = 24;
  targetWorksheet.getRow(15).height = 0;
  targetWorksheet.getRow(15).hidden = true;
  targetWorksheet.getRow(16).height = 18;
  targetWorksheet.getRow(17).height = 30;
  targetWorksheet.getRow(30).height = 24;
}

/**
 * Adds the formatted summary worksheet to the workbook.
 * @param workbook Target workbook.
 * @param labels Localized export labels.
 * @param screenName Screen display name.
 * @param summaryStatistics Summary statistics used to populate the sheet.
 */
export function addSummarySheet(
  workbook: Workbook,
  labels: NpsExcelExportLabels,
  screenName: string,
  summaryStatistics: SummaryStatistics,
): void {
  const worksheet = workbook.addWorksheet(
    createWorksheetName(labels.summarySheetName, 'Summary'),
  );
  const computedValues = buildSummaryComputedValues(labels, summaryStatistics);

  worksheet.columns = [
    { width: 6.2 },
    { width: 6.2 },
    { width: 6.2 },
    { width: 6.2 },
    { width: 6.2 },
    { width: 2 },
    { width: 6.2 },
    { width: 6.2 },
    { width: 6.2 },
    { width: 6.2 },
    { width: 6.2 },
    { width: 2 },
    { width: 6.2 },
    { width: 6.2 },
    { width: 6.2 },
    { width: 6.2 },
    { width: 6.2 },
