import type {
  NpsExcelExportLabels,
  SummaryStatistics,
} from '../types/nps-export.types';

interface WorkbookZipFile {
  async(type: 'string'): Promise<string>;
}

interface WorkbookZip {
  file(path: string): WorkbookZipFile | null;
  file(path: string, data: string): unknown;
  files: Record<string, unknown>;
  generateAsync(options: { type: 'arraybuffer' }): Promise<ArrayBuffer>;
}

const CHART_NAMES = {
  distribution: 'Score distribution chart',
} as const;

const SUMMARY_LAYOUT = {
  chartFromColumn: 1,
  chartFromRow: 18,
  chartToColumn: 22,
  chartToRow: 29,
} as const;

const XML_DECLARATION =
  '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>';
const XML_PARSER_ERROR_SELECTOR = 'parsererror';

const XML_NAMESPACES = {
  chart: 'http://schemas.openxmlformats.org/drawingml/2006/chart',
  contentTypes: 'http://schemas.openxmlformats.org/package/2006/content-types',
  drawing: 'http://schemas.openxmlformats.org/drawingml/2006/main',
  packageRelationships:
    'http://schemas.openxmlformats.org/package/2006/relationships',
  spreadsheet: 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
  spreadsheetDrawing:
    'http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing',
  workbookRelationships:
    'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
} as const;

type ReplaceAllFunction = (
  this: string,
  searchValue: string | RegExp,
  replaceValue: string,
) => string;

const stringReplaceAll = (
  String.prototype as unknown as {
    replaceAll: ReplaceAllFunction;
  }
).replaceAll;

/**
 * Applies String#replaceAll via the runtime prototype while keeping compatibility with the project's TS lib target.
 * @param value Source string.
 * @param searchValue Substring or global regular expression to replace.
 * @param replaceValue Replacement text.
 * @returns Updated string value.
 */
function callReplaceAll(
  value: string,
  searchValue: string | RegExp,
  replaceValue: string,
): string {
  return stringReplaceAll.call(value, searchValue, replaceValue);
}

/**
 * Escapes XML-sensitive characters in text content.
 * @param value Raw text content.
 * @returns XML-safe text.
 */
function escapeXml(value: string): string {
  return callReplaceAll(
    callReplaceAll(
      callReplaceAll(
        callReplaceAll(callReplaceAll(value, '&', '&amp;'), '<', '&lt;'),
        '>',
        '&gt;',
      ),
      '"',
      '&quot;',
    ),
    "'",
    '&apos;',
  );
}

/**
 * Converts an ARGB color to the SRGB value expected by chart XML.
 * @param argbColor ARGB color string.
 * @returns SRGB color value.
 */
function toSrgbColor(argbColor: string): string {
  return argbColor.slice(2);
}

/**
 * Parses XML text into a DOM document.
 * @param xml XML payload.
 * @returns Parsed XML document.
 */
function createXmlDocument(xml: string): XMLDocument {
  const documentNode = new DOMParser().parseFromString(xml, 'application/xml');

  if (documentNode.querySelector(XML_PARSER_ERROR_SELECTOR)) {
    throw new Error('Unable to parse workbook XML.');
  }

  return documentNode;
}

/**
 * Serializes an XML document and ensures the XML declaration is present.
 * @param documentNode XML document to serialize.
 * @returns Serialized XML string.
 */
function serializeXmlDocument(documentNode: XMLDocument): string {
  const serializedValue = new XMLSerializer().serializeToString(documentNode);

  return serializedValue.startsWith('<?xml')
    ? serializedValue
    : `${XML_DECLARATION}\n${serializedValue}`;
}

/**
 * Creates an empty relationships XML document.
 * @returns Relationships XML document.
 */
function createRelationshipDocument(): XMLDocument {
  return createXmlDocument(
    `${XML_DECLARATION}<Relationships xmlns="${XML_NAMESPACES.packageRelationships}"/>`,
  );
}

/**
 * Resolves a part path relative to a workbook XML source path.
 * @param sourcePath Source workbook path.
 * @param targetPath Target relationship path.
 * @returns Resolved workbook part path.
 */
function resolveRelativePartPath(
  sourcePath: string,
  targetPath: string,
): string {
  if (targetPath.startsWith('/')) {
    return targetPath.slice(1);
  }

  const resolvedSegments = sourcePath.split('/');

  resolvedSegments.pop();

  for (const segment of targetPath.split('/')) {
    if (segment === '..') {
      resolvedSegments.pop();
    } else if (segment !== '.' && segment.length > 0) {
      resolvedSegments.push(segment);
    }
  }

  return resolvedSegments.join('/');
}

/**
 * Resolves the next available relationship id for a package relationships file.
 * @param documentNode Relationships XML document.
 * @returns Next relationship id.
 */
function getNextRelationshipId(documentNode: XMLDocument): string {
  const relationshipElements = [
    ...documentNode.getElementsByTagNameNS(
      XML_NAMESPACES.packageRelationships,
      'Relationship',
    ),
  ];
  let highestIndex = 0;

  for (const element of relationshipElements) {
    const idValue = element.getAttribute('Id') ?? '';
    const numericValue = Number.parseInt(idValue.replace('rId', ''), 10);

    if (!Number.isNaN(numericValue)) {
      highestIndex = Math.max(highestIndex, numericValue);
    }
  }

  return `rId${highestIndex + 1}`;
}

/**
 * Appends a relationship entry to a relationships XML document.
 * @param documentNode Relationships XML document.
 * @param id Relationship identifier.
 * @param type Relationship type URI.
 * @param target Relationship target path.
 */
function appendRelationship(
  documentNode: XMLDocument,
  id: string,
  type: string,
  target: string,
): void {
  const relationshipElement = documentNode.createElementNS(
    XML_NAMESPACES.packageRelationships,
    'Relationship',
  );

  relationshipElement.setAttribute('Id', id);
  relationshipElement.setAttribute('Type', type);
  relationshipElement.setAttribute('Target', target);
  documentNode.documentElement.append(relationshipElement);
}

/**
 * Escapes a string for use inside a regular expression.
 * @param value Raw string fragment.
 * @returns Escaped regular-expression fragment.
 */
function escapeRegExp(value: string): string {
  return callReplaceAll(value, /[.*+?^${}()|[\]\\]/gu, String.raw`\$&`);
}

/**
 * Resolves the next numeric part index for generated workbook artifacts.
 * @param fileNames Existing file names in the package.
 * @param prefix File name prefix.
 * @param suffix File name suffix.
 * @returns Next available numeric index.
 */
function findNextPartIndex(
  fileNames: Array<string>,
  prefix: string,
  suffix: string,
): number {
  const escapedPrefix = escapeRegExp(prefix);
  const escapedSuffix = escapeRegExp(suffix);
  const pattern = new RegExp(
    String.raw`^${escapedPrefix}(\d+)${escapedSuffix}$`,
    'u',
  );

  let highestValue = 0;

  for (const fileName of fileNames) {
    const matchedGroups = pattern.exec(fileName);

    if (matchedGroups) {
      const nextValue = Number.parseInt(matchedGroups[1], 10);

      if (!Number.isNaN(nextValue)) {
        highestValue = Math.max(highestValue, nextValue);
      }
    }
  }

  return highestValue + 1;
}

/**
 * Loads the workbook zip helper and parses the workbook buffer.
 * @param buffer Workbook binary buffer.
 * @returns Parsed workbook zip archive.
 */
async function loadWorkbookZip(buffer: ArrayBuffer): Promise<WorkbookZip> {
  const { default: jsZip } = await import('jszip');

  return (await jsZip.loadAsync(buffer)) as unknown as WorkbookZip;
}

/**
 * Reads a text file from the workbook zip package.
 * @param zip Loaded workbook zip archive.
 * @param filePath Target file path inside the archive.
 * @returns File text or undefined when the file is missing.
 */
async function readZipText(
  zip: WorkbookZip,
  filePath: string,
): Promise<string | undefined> {
  const zipFile = zip.file(filePath);

  if (!zipFile) {
    return undefined;
  }

  return zipFile.async('string');
}

/**
 * Resolves the worksheet XML part path for the summary sheet.
 * @param zip Loaded workbook zip archive.
 * @param worksheetName Summary worksheet name.
 * @returns Worksheet part path.
 */
async function resolveWorksheetPartPath(
  zip: WorkbookZip,
  worksheetName: string,
): Promise<string> {
  const workbookXml = await readZipText(zip, 'xl/workbook.xml');
  const workbookRelsXml = await readZipText(zip, 'xl/_rels/workbook.xml.rels');

  if (!workbookXml || !workbookRelsXml) {
    throw new Error('Workbook metadata is missing from the Excel export.');
  }

  const workbookDocument = createXmlDocument(workbookXml);
  const workbookRelsDocument = createXmlDocument(workbookRelsXml);
  const sheetElements = [
    ...workbookDocument.getElementsByTagNameNS(
      XML_NAMESPACES.spreadsheet,
      'sheet',
    ),
  ];
  const targetSheet = sheetElements.find(
    (sheetElement) => sheetElement.getAttribute('name') === worksheetName,
  );

  if (!targetSheet) {
    throw new Error('Unable to locate the summary worksheet in the workbook.');
  }

  const relationshipId =
    targetSheet.getAttributeNS(XML_NAMESPACES.workbookRelationships, 'id') ??
    targetSheet.getAttribute('r:id');

  if (!relationshipId) {
    throw new Error('Summary worksheet relationship metadata is missing.');
  }

  const relationshipElements = [
    ...workbookRelsDocument.getElementsByTagNameNS(
      XML_NAMESPACES.packageRelationships,
      'Relationship',
    ),
  ];
  const targetRelationship = relationshipElements.find(
    (relationshipElement) =>
      relationshipElement.getAttribute('Id') === relationshipId,
  );

  if (!targetRelationship) {
    throw new Error('Unable to resolve the summary worksheet target.');
  }

  return resolveRelativePartPath(
    'xl/workbook.xml',
    targetRelationship.getAttribute('Target') ?? '',
  );
}

/**
 * Ensures a worksheet XML payload references the generated drawing part.
 * @param worksheetXml Worksheet XML payload.
 * @param drawingRelationshipId Drawing relationship id.
 * @returns Updated worksheet XML payload.
 */
function ensureWorksheetDrawingXml(
  worksheetXml: string,
  drawingRelationshipId: string,
): string {
  const drawingNode = `<drawing r:id="${drawingRelationshipId}"/>`;

  if (worksheetXml.includes('<drawing ')) {
    return worksheetXml.replace(
      /<drawing\b[^>]*\br:id="[^"]*"\s*\/>/u,
      drawingNode,
    );
  }

  if (/<extLst\b/u.test(worksheetXml)) {
    return callReplaceAll(worksheetXml, /<extLst\b/gu, `${drawingNode}<extLst`);
  }

  if (worksheetXml.includes('<legacyDrawing ')) {
    return callReplaceAll(
      worksheetXml,
      /<legacyDrawing\b/gu,
      `${drawingNode}<legacyDrawing`,
    );
  }

  return worksheetXml.replace('</worksheet>', `${drawingNode}</worksheet>`);
}

/**
 * Ensures the workbook content types file includes a part override.
 * @param documentNode Content types XML document.
 * @param partName Part name to register.
 * @param contentType Content type value.
 */
function ensureContentTypeOverride(
  documentNode: XMLDocument,
  partName: string,
  contentType: string,
): void {
  const overrideElements = [
    ...documentNode.getElementsByTagNameNS(
      XML_NAMESPACES.contentTypes,
      'Override',
    ),
  ];
  const hasOverride = overrideElements.some(
    (overrideElement) => overrideElement.getAttribute('PartName') === partName,
  );

  if (!hasOverride) {
    const overrideElement = documentNode.createElementNS(
      XML_NAMESPACES.contentTypes,
      'Override',
    );

    overrideElement.setAttribute('PartName', partName);
    overrideElement.setAttribute('ContentType', contentType);
    documentNode.documentElement.append(overrideElement);
  }
}

/**
 * Builds cached chart category XML points.
 * @param values Category values.
 * @returns XML point list.
