function createCategoryCacheXml(values: Array<string>): string {
  return values
    .map(
      (value, index) =>
        `<c:pt idx="${index}"><c:v>${escapeXml(value)}</c:v></c:pt>`,
    )
    .join('');
}

/**
 * Builds cached chart numeric XML points.
 * @param values Numeric values.
 * @returns XML point list.
 */
function createNumberCacheXml(values: Array<number>): string {
  return values
    .map((value, index) => `<c:pt idx="${index}"><c:v>${value}</c:v></c:pt>`)
    .join('');
}

