/**
 * Builds the XML anchor for a chart drawing.
 * @param relationshipId Chart relationship id.
 * @param chartName Chart display name.
 * @param graphicFrameId Graphic frame identifier.
 * @param fromColumn Starting column index.
 * @param fromRow Starting row index.
 * @param toColumn Ending column index.
 * @param toRow Ending row index.
 * @returns Drawing anchor XML payload.
 */
function createChartAnchorXml(
  relationshipId: string,
  chartName: string,
  graphicFrameId: number,
  fromColumn: number,
  fromRow: number,
  toColumn: number,
  toRow: number,
): string {
  return `<xdr:twoCellAnchor><xdr:from><xdr:col>${fromColumn}</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>${fromRow}</xdr:row><xdr:rowOff>0</xdr:rowOff></xdr:from><xdr:to><xdr:col>${toColumn}</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>${toRow}</xdr:row><xdr:rowOff>0</xdr:rowOff></xdr:to><xdr:graphicFrame macro=""><xdr:nvGraphicFramePr><xdr:cNvPr id="${graphicFrameId}" name="${escapeXml(chartName)}"/><xdr:cNvGraphicFramePr/></xdr:nvGraphicFramePr><xdr:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/></xdr:xfrm><a:graphic><a:graphicData uri="${XML_NAMESPACES.chart}"><c:chart xmlns:c="${XML_NAMESPACES.chart}" xmlns:r="${XML_NAMESPACES.workbookRelationships}" r:id="${relationshipId}"/></a:graphicData></a:graphic></xdr:graphicFrame><xdr:clientData/></xdr:twoCellAnchor>`;
}

/**
 * Builds the worksheet drawing XML for the distribution chart.
 * @param distributionRelationshipId Distribution chart relationship id.
 * @returns Worksheet drawing XML payload.
 */
function createDrawingXml(distributionRelationshipId: string): string {
