</xdr:wsDr>`;
}

/**
 * Builds drawing relationships XML for generated charts.
 * @param chartRelationshipId Chart relationship id.
 * @param chartPath Chart file name.
 * @returns Drawing relationships XML payload.
 */
function createDrawingRelationshipsXml(
  chartRelationshipId: string,
  chartPath: string,
): string {
  return `${XML_DECLARATION}<Relationships xmlns="${XML_NAMESPACES.packageRelationships}"><Relationship Id="${chartRelationshipId}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/chart" Target="../charts/${chartPath}"/></Relationships>`;
}

/**
 * Injects native Excel chart XML into the generated workbook package.
 * @param buffer Workbook binary buffer.
 * @param summarySheetName Summary worksheet name.
 * @param labels Localized export labels.
 * @param summaryStatistics Summary statistics used by the chart.
 * @returns Updated workbook buffer containing the native chart parts.
 */
export async function injectNativeCharts(
  buffer: ArrayBuffer,
  summarySheetName: string,
  labels: NpsExcelExportLabels,
  summaryStatistics: SummaryStatistics,
): Promise<ArrayBuffer> {
  const zip = await loadWorkbookZip(buffer);
  const worksheetPath = await resolveWorksheetPartPath(zip, summarySheetName);
  const worksheetXml = await readZipText(zip, worksheetPath);

  if (!worksheetXml) {
    throw new Error('Unable to read the summary worksheet XML.');
  }

  const worksheetFileName = worksheetPath.split('/').at(-1);

  if (!worksheetFileName) {
    throw new Error('Summary worksheet file name is invalid.');
  }

  const worksheetRelsPath = `xl/worksheets/_rels/${worksheetFileName}.rels`;
  const worksheetRelsXml = await readZipText(zip, worksheetRelsPath);
  const worksheetRelsDocument = worksheetRelsXml
    ? createXmlDocument(worksheetRelsXml)
    : createRelationshipDocument();
  const allFileNames = Object.keys(zip.files);
  const nextDrawingIndex = findNextPartIndex(
    allFileNames,
    'xl/drawings/drawing',
    '.xml',
  );
  const nextChartIndex = findNextPartIndex(
    allFileNames,
    'xl/charts/chart',
    '.xml',
  );
  const drawingFileName = `drawing${nextDrawingIndex}.xml`;
  const drawingPath = `xl/drawings/${drawingFileName}`;
  const drawingRelationshipId = getNextRelationshipId(worksheetRelsDocument);

  const worksheetXmlWithDrawing = ensureWorksheetDrawingXml(
    worksheetXml,
    drawingRelationshipId,
  );
  appendRelationship(
    worksheetRelsDocument,
    drawingRelationshipId,
    'http://schemas.openxmlformats.org/officeDocument/2006/relationships/drawing',
    `../drawings/${drawingFileName}`,
  );

  const distributionChartFileName = `chart${nextChartIndex}.xml`;
  const distributionChartRelationshipId = 'rId1';

  zip.file(
    `xl/charts/${distributionChartFileName}`,
    createDistributionChartXml(labels, summaryStatistics),
  );
  zip.file(drawingPath, createDrawingXml(distributionChartRelationshipId));
  zip.file(
    `xl/drawings/_rels/${drawingFileName}.rels`,
    createDrawingRelationshipsXml(
      distributionChartRelationshipId,
      distributionChartFileName,
    ),
  );
  zip.file(worksheetPath, worksheetXmlWithDrawing);
  zip.file(worksheetRelsPath, serializeXmlDocument(worksheetRelsDocument));

  const contentTypesXml = await readZipText(zip, '[Content_Types].xml');

  if (!contentTypesXml) {
    throw new Error(
      'Workbook content types are missing from the export package.',
    );
  }

  const contentTypesDocument = createXmlDocument(contentTypesXml);

  ensureContentTypeOverride(
    contentTypesDocument,
    `/${drawingPath}`,
    'application/vnd.openxmlformats-officedocument.drawing+xml',
  );
  ensureContentTypeOverride(
    contentTypesDocument,
    `/xl/charts/${distributionChartFileName}`,
    'application/vnd.openxmlformats-officedocument.drawingml.chart+xml',
  );
  zip.file('[Content_Types].xml', serializeXmlDocument(contentTypesDocument));

  return zip.generateAsync({ type: 'arraybuffer' });
}

