  right: { color: { argb: 'FFCCD6E0' }, style: 'thin' },
  top: { color: { argb: 'FFCCD6E0' }, style: 'thin' },
} as const;

const NPS_SCORE_THRESHOLDS = {
  passive: 7,
  promoter: 9,
} as const;

/**
 * Builds a filesystem-safe export file name from the screen name.
 * @param screenName Screen name to normalize.
 * @returns Lower-cased kebab-case file name without extension.
 */
function createExportFileName(screenName: string): string {
  let fileName = '';
  let previousWasSeparator = false;

  for (const character of screenName.trim().toLowerCase()) {
    const isAlphaNumeric = /[\da-z]/.test(character);

    if (isAlphaNumeric) {
      fileName += character;
      previousWasSeparator = false;
    } else if (!previousWasSeparator && fileName.length > 0) {
      fileName += '-';
      previousWasSeparator = true;
    }
  }

  return previousWasSeparator ? fileName.slice(0, -1) : fileName;
}

/**
 * Creates a valid Excel worksheet name with the workbook length limit applied.
 * @param baseName Requested worksheet name.
 * @param fallbackName Fallback worksheet name when the requested value is empty.
 * @returns Worksheet name truncated to Excel's maximum length.
 */
function createWorksheetName(baseName: string, fallbackName: string): string {
  const normalizedName = baseName.trim() || fallbackName;

  return normalizedName.slice(0, 31);
}

/**
 * Resolves the distribution category label for a score.
 * @param score NPS score value.
 * @param labels Localized export labels.
 * @returns Localized category label.
 */
function resolveDistributionCategoryLabel(
  score: number,
  labels: NpsExcelExportLabels,
): string {
  if (score >= NPS_SCORE_THRESHOLDS.promoter) {
    return labels.promotersLabel;
  }

  if (score >= NPS_SCORE_THRESHOLDS.passive) {
    return labels.passivesLabel;
  }

  return labels.detractorsLabel;
}

/**
 * Applies a solid fill color to a worksheet cell.
 * @param cell Target worksheet cell.
 * @param fillColor ARGB fill color.
 */
function applyFill(cell: Cell, fillColor: string): void {
  const targetCell = cell;

  targetCell.fill = {
    fgColor: { argb: fillColor },
    pattern: 'solid',
    type: 'pattern',
  };
}

/**
 * Builds a full name from an NPS response record.
 * @param response NPS response record.
 * @returns Concatenated full name.
 */
function createFullName(response: NpsResponseRecord): string {
  return [response.firstName, response.lastName]
    .map((value) => value?.trim() ?? '')
    .filter((value) => value.length > 0)
    .join(' ');
}

/**
 * Parses the response update timestamp into a Date when valid.
 * @param lastUpdated Raw response timestamp.
 * @returns Date instance or the original timestamp.
 */
function parseResponseDate(lastUpdated: string): Date | string {
  const date = new Date(lastUpdated);

  return Number.isNaN(date.getTime()) ? lastUpdated : date;
}

/**
 * Maps a score to an export feedback category.
 * @param score NPS score value.
 * @returns Export category key or undefined when the score is missing.
 */
function resolveCategoryKey(score: number | null): NpsExcelCategoryKey {
  if (score === null) {
    return undefined;
  }

  if (score >= NPS_SCORE_THRESHOLDS.promoter) {
    return 'promoter';
  }

  if (score >= NPS_SCORE_THRESHOLDS.passive) {
    return 'passive';
  }

  return 'detractor';
}

/**
 * Maps a score to the localized export category label.
 * @param score NPS score value.
 * @param labels Localized export labels.
 * @returns Localized category label.
 */
function resolveCategoryLabel(
  score: number | null,
  labels: NpsExcelExportLabels,
): string {
  const categoryKey = resolveCategoryKey(score);

  if (categoryKey === undefined) {
    return '';
  }

  switch (categoryKey) {
    case 'promoter': {
      return labels.promoter;
    }
    case 'passive': {
      return labels.passive;
    }
    default: {
      return labels.detractor;
    }
  }
}

/**
 * Resolves the accent color for a score category.
 * @param score NPS score value.
 * @returns ARGB accent color.
 */
function resolveCategoryAccent(score: number): string {
  if (score >= NPS_SCORE_THRESHOLDS.promoter) {
    return PROMOTER_ACCENT;
  }

  if (score >= NPS_SCORE_THRESHOLDS.passive) {
    return PASSIVE_ACCENT;
  }

  return DETRACTOR_ACCENT;
}

/**
 * Validates scores for chart distribution rendering.
 * @param score NPS score value.
 * @returns Integer score between 0 and 10 or undefined when invalid.
 */
function normalizeChartScore(score: number | null): number | undefined {
  if (typeof score !== 'number' || !Number.isInteger(score)) {
    return undefined;
  }

  if (score < 0 || score > 10) {
    return undefined;
  }

  return score;
}

/**
 * Builds aggregate statistics used by the summary sheet.
 * @param responses NPS response records.
 * @param labels Localized export labels.
 * @returns Summary statistics for chart and card rendering.
 */
function buildSummaryStatistics(
  responses: Array<NpsResponseRecord>,
  labels: NpsExcelExportLabels,
): SummaryStatistics {
  const scoreCounts = Array.from({ length: 11 }, () => 0);

  for (const response of responses) {
    const normalizedScore = normalizeChartScore(response.score);

    if (normalizedScore !== undefined) {
      scoreCounts[normalizedScore] += 1;
    }
  }

  let totalResponses = 0;

  for (const currentValue of scoreCounts) {
    totalResponses += currentValue;
  }

  const promoterCount = scoreCounts[9] + scoreCounts[10];
  const passiveCount = scoreCounts[7] + scoreCounts[8];
  let detractorCount = 0;

  for (const currentValue of scoreCounts.slice(0, 7)) {
    detractorCount += currentValue;
  }

  const distribution = scoreCounts.map((count, score) => ({
    category: resolveDistributionCategoryLabel(score, labels),
    color: resolveCategoryAccent(score),
    count,
    score,
    share: totalResponses === 0 ? 0 : count / totalResponses,
  }));
  const categoryMix = [
    {
      color: DETRACTOR_ACCENT,
      count: detractorCount,
      label: labels.detractorsLabel,
      share: totalResponses === 0 ? 0 : detractorCount / totalResponses,
    },
    {
      color: PASSIVE_ACCENT,
      count: passiveCount,
      label: labels.passivesLabel,
      share: totalResponses === 0 ? 0 : passiveCount / totalResponses,
    },
    {
      color: PROMOTER_ACCENT,
      count: promoterCount,
      label: labels.promotersLabel,
      share: totalResponses === 0 ? 0 : promoterCount / totalResponses,
    },
  ];

  return {
    categoryMix,
    distribution,
    totalResponses,
  };
}

/**
 * Maps raw responses to worksheet rows.
 * @param responses NPS response records.
 * @param labels Localized export labels.
 * @returns Data rows for the export worksheet.
 */
function buildExportRows(
  responses: Array<NpsResponseRecord>,
  labels: NpsExcelExportLabels,
): Array<ExportRow> {
  return responses.map((response, index) => ({
    category: resolveCategoryLabel(response.score, labels),
    comment: response.comment?.trim() ?? '',
    date: parseResponseDate(response.lastUpdated),
    fullName: createFullName(response),
    id: index + 1,
    plant: response.plant ?? '',
    release: response.release?.trim() ?? '',
    responseType: response.responseType?.trim() ?? '',
    role: Array.isArray(response.roleName)
      ? response.roleName.join(', ')
      : (response.roleName ?? ''),
    score: response.score ?? '',
  }));
}

/**
 * Styles the exported response worksheet.
 * @param worksheet Target response worksheet.
 * @param rowCount Number of data rows to style.
 */
function styleDataArea(worksheet: Worksheet, rowCount: number): void {
  const targetWorksheet = worksheet;

  targetWorksheet.columns = [
    { key: 'id', width: 8 },
    { key: 'date', width: 14 },
    { key: 'fullName', width: 28 },
    { key: 'plant', width: 12 },
    { key: 'role', width: 20 },
    { key: 'comment', width: 44 },
    { key: 'score', width: 10 },
    { key: 'category', width: 18 },
    { key: 'release', width: 18 },
  ];

  targetWorksheet.views = [{ state: 'frozen', ySplit: 1 }];
  targetWorksheet.autoFilter = {
    from: 'A1',
    to: 'I1',
  };

  const headerRow = targetWorksheet.getRow(1);

  headerRow.font = { bold: true };
  headerRow.alignment = { horizontal: 'center', vertical: 'middle' };
  headerRow.height = 22;

  for (let columnNumber = 1; columnNumber <= 9; columnNumber += 1) {
    const cell = headerRow.getCell(columnNumber);

    applyFill(cell, DATA_HEADER_FILL);
    cell.border = THIN_BORDER;
  }

  for (let rowNumber = 2; rowNumber <= rowCount + 1; rowNumber += 1) {
    const row = targetWorksheet.getRow(rowNumber);
    const rowFill = rowNumber % 2 === 0 ? SURFACE_FILL : MUTED_SURFACE_FILL;

    row.height = 24;

    for (let columnNumber = 1; columnNumber <= 9; columnNumber += 1) {
      const cell = row.getCell(columnNumber);

      cell.alignment = {
        horizontal:
          columnNumber === 1 || columnNumber === 4 || columnNumber === 7
            ? 'center'
            : 'left',
        vertical: 'middle',
        wrapText: columnNumber === 6,
      };
      cell.border = THIN_BORDER;
      applyFill(cell, rowFill);
    }

    const dateCell = row.getCell(2);

    if (dateCell.value instanceof Date) {
      dateCell.numFmt = 'm/d/yyyy';
    }
  }
}

/**
 * Triggers a browser download for the generated workbook buffer.
 * @param buffer Workbook binary buffer.
 * @param fileName Target download file name.
 */
function downloadBuffer(buffer: ArrayBuffer, fileName: string): void {
  const blob = new Blob([buffer], {
    type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  });
  const objectUrl = URL.createObjectURL(blob);
  const link = document.createElement('a');

  link.href = objectUrl;
  link.download = fileName;
  document.body.append(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(objectUrl);
}

/**
 * Exports the provided NPS responses into a styled Excel workbook.
 * @param options Export options including labels, responses, and screen metadata.
 * @param options.labels Localized labels used in the workbook.
 * @param options.responses Response records to export.
 * @param options.screen Screen metadata used for workbook naming.
 * @returns Promise that resolves after the workbook is generated and downloaded.
 */
export async function exportNpsResponsesToExcel(
  options: NpsExcelExportOptions,
): Promise<void> {
  const { labels, responses, screen } = options;
  const exceljsModule = await import('exceljs');
  const workbook = new exceljsModule.Workbook();
  const dataSheetName = createWorksheetName(labels.dataSheetName, 'Responses');
  const worksheet = workbook.addWorksheet(dataSheetName);
  const submittedResponses = responses.filter(
    (response) => response.responseType?.trim().toUpperCase() === 'SUBMITTED',
  );
  const exportRows = buildExportRows(submittedResponses, labels);
  const summaryStatistics = buildSummaryStatistics(submittedResponses, labels);

  workbook.calcProperties.fullCalcOnLoad = true;

  worksheet.addRow([
    labels.id,
    labels.date,
    labels.fullName,
    labels.plant,
    labels.role,
    labels.comment,
    labels.score,
    labels.category,
    labels.release,
  ]);

  for (const exportRow of exportRows) {
    worksheet.addRow([
      exportRow.id,
      exportRow.date,
      exportRow.fullName,
      exportRow.plant,
      exportRow.role,
      exportRow.comment,
      exportRow.score,
      exportRow.category,
      exportRow.release,
    ]);
  }

  styleDataArea(worksheet, exportRows.length);
  addSummarySheet(workbook, labels, screen.name, summaryStatistics);

  const buffer = await workbook.xlsx.writeBuffer();
  const workbookBuffer = await injectNativeCharts(
    buffer as ArrayBuffer,
    createWorksheetName(labels.summarySheetName, 'Summary'),
    labels,
    summaryStatistics,
  );

  downloadBuffer(
    workbookBuffer,
    `${createExportFileName(screen.name)}-nps-export.xlsx`,
  );
}

import { ref } from 'vue';

/**
 * Composable for handling assignment dialog state and actions.
 * @returns Assignment dialog state and handlers.
 */
export function useAssignDialog(): {
  assignDialogOpen: ReturnType<typeof ref<boolean>>;
  assignInitialResourceIds: ReturnType<typeof ref<Array<string>>>;
  handleApply: (ids: Array<string>) => void;
  handleCancel: () => void;
  openAssignDialog: (initialIds?: Array<string>) => Promise<Array<string>>;
} {
  // Always ensure assignDialogOpen is boolean, never undefined
  const assignDialogOpen = ref<boolean>(false);
  // Defensive: always set to false, never undefined
  // Removed unused setAssignDialogOpen function
  const assignInitialResourceIds = ref<Array<string>>([]);
  const assignPromise = ref<undefined | ((ids: Array<string>) => void)>(
    undefined,
  );

  /**
   * Opens the assignment dialog.
   * @param initialIds Initial resource IDs to pre-select.
   * @returns Promise resolving with selected IDs.
   */
  function openAssignDialog(
    initialIds: Array<string> = [],
  ): Promise<Array<string>> {
    assignInitialResourceIds.value = initialIds;
    assignDialogOpen.value = true;
    return new Promise((resolve) => {
      assignPromise.value = resolve;
    });
  }

  /**
   * Handles apply action in dialog.
   * @param ids Selected resource IDs.
   */
  function handleApply(ids: Array<string>): void {
    assignDialogOpen.value = false;
    if (assignPromise.value) {
      assignPromise.value(ids);
      assignPromise.value = undefined;
    }
  }

  /**
   * Handles cancel action in dialog.
   */
  function handleCancel(): void {
    assignDialogOpen.value = false;
    if (assignPromise.value) {
      assignPromise.value([]);
      assignPromise.value = undefined;
    }
  }

  return {
    assignDialogOpen,
    assignInitialResourceIds,
    handleApply,
    handleCancel,
    openAssignDialog,
  };
}

import {
  getHierarchy,
  type HierarchyPlantDto,
} from '../services/hierarchy-api';
import { getTemplatesByPlant } from '../services/template-api';
import { useTemplateStore } from '../store/template-store';
import { i18n } from '@/localization/i18n';
import { useProfileStore } from '@/store/user-auth-store';

const EDASHBOARD_SCREEN_ID = 32;
const LIVE_STATUS_SCREEN_ID = 33;
const GAP_SCOPE_TYPE = 'GAP';
const RESOURCE_SCOPE_TYPE = 'RESOURCE';

/**
 * Resolves the assigned scope type from the current template scope list.
 * @param scopeList The template scope entries.
 * @returns The prioritized scope type, if one is assigned.
 */
function getAssignedScopeType(
  scopeList: Array<{ scopeType?: string; scopeValue?: string }> | undefined,
): string | undefined {
  const types = new Set(
    (scopeList ?? [])
      .map((scope) =>
        String(scope?.scopeType ?? '')
          .trim()
          .toUpperCase(),
      )
      .filter(
        (scopeType) =>
          scopeType === GAP_SCOPE_TYPE || scopeType === RESOURCE_SCOPE_TYPE,
      ),
  );

  if (types.has(RESOURCE_SCOPE_TYPE)) {
    return RESOURCE_SCOPE_TYPE;
  }

  if (types.has(GAP_SCOPE_TYPE)) {
    return GAP_SCOPE_TYPE;
  }

  return undefined;
}

/**
 * Resolves the active screen id for the current template context.
 * @param screens The screens assigned to the template.
 * @param scopeList The template scope entries.
 * @returns The screen id used to evaluate publish conflicts.
 */
function resolveActiveScreenId(
  screens: Array<{ screenId?: number; screenName?: string }> | undefined,
  scopeList?: Array<{ scopeType?: string; scopeValue?: string }>,
): number | undefined {
  const assignedScopeType = getAssignedScopeType(scopeList);
  if (assignedScopeType === RESOURCE_SCOPE_TYPE) {
    return EDASHBOARD_SCREEN_ID;
  }

  if (assignedScopeType === GAP_SCOPE_TYPE) {
    return LIVE_STATUS_SCREEN_ID;
  }

  const ids = Array.isArray(screens)
    ? screens
        .map((screen) =>
          typeof screen?.screenId === 'number' ? screen.screenId : undefined,
        )
        .filter((screenId): screenId is number => screenId !== undefined)
    : [];

  if (ids.includes(EDASHBOARD_SCREEN_ID)) {
    return EDASHBOARD_SCREEN_ID;
  }

  if (ids.includes(LIVE_STATUS_SCREEN_ID)) {
    return LIVE_STATUS_SCREEN_ID;
  }

  return ids[0];
}

/**
 * Resolves the scope type associated with the active screen id.
 * @param screenId The active screen id.
 * @returns The scope type used for publish conflict checks.
 */
function resolveScopeType(screenId: number | undefined): string {
  return screenId === LIVE_STATUS_SCREEN_ID
    ? GAP_SCOPE_TYPE
    : RESOURCE_SCOPE_TYPE;
}

/**
 * Composable for publish warning logic.
 * @returns Publish warning checker.
 */
export interface PublishScopeConflict {
  scopeLabel?: string;
  scopeType: string;
  scopeValue: string;
  templateLabel: string;
}

/**
 * Flattens hierarchy data into resource entries.
 * @param hierarchy Hierarchy tree returned by the backend.
 * @returns Resource entries across all hierarchy levels.
 */
function collectHierarchyResources(
  hierarchy: Array<HierarchyPlantDto>,
): Array<
  NonNullable<
    NonNullable<
      NonNullable<
        NonNullable<HierarchyPlantDto['uaps']>[number]['productionLines']
      >[number]['workcenters']
    >[number]['resources']
  >[number]
> {
  const resources: Array<
    NonNullable<
      NonNullable<
        NonNullable<
          NonNullable<HierarchyPlantDto['uaps']>[number]['productionLines']
        >[number]['workcenters']
      >[number]['resources']
    >[number]
  > = [];

  for (const plant of hierarchy) {
    for (const uap of plant.uaps ?? []) {
      for (const line of uap.productionLines ?? []) {
        for (const workcenter of line.workcenters ?? []) {
          resources.push(...(workcenter.resources ?? []));
        }
      }
    }
  }

  return resources;
}

/**
 * Builds a map from scope ids to display labels.
 * @param hierarchy Hierarchy tree returned by the backend.
 * @param scopeType The selected scope type.
 * @returns Display labels keyed by scope id.
 */
function buildScopeLabelMap(
  hierarchy: Array<HierarchyPlantDto>,
  scopeType: string,
): Map<string, string> {
  const labels = new Map<string, string>();

  for (const resource of collectHierarchyResources(hierarchy)) {
    const id =
      scopeType === GAP_SCOPE_TYPE
        ? String(resource.gapId ?? '').trim()
        : String(resource.resourceId ?? '').trim();
    const label =
      scopeType === GAP_SCOPE_TYPE
        ? String(resource.gapDesc ?? '').trim()
        : String(resource.resourceName ?? '').trim();

    if (id) {
      labels.set(id, label || id);
    }
  }

  return labels;
}

/**
 * Loads display labels for the active scope type.
 * @param scopeType The selected scope type.
 * @returns Display labels keyed by scope id.
 */
async function loadScopeLabels(
  scopeType: string,
): Promise<Map<string, string>> {
  const userId = String(localStorage.getItem('userId') ?? '').trim();
  if (!userId) return new Map();

  try {
    return buildScopeLabelMap(await getHierarchy(userId), scopeType);
  } catch {
    return new Map();
  }
}
/**
 * Composable for publish warning logic.
 * @returns Publish warning checker with conflict detection functionality.
 */
export function usePublishWarning(): {
  checkAlreadyAssignedOnPublish: () => Promise<Array<PublishScopeConflict>>;
} {
  const templateStore = useTemplateStore();
  const profileStore = useProfileStore();

  /**
   * Checks if selected resources are already assigned to other published templates.
   * @returns All detected resource/template conflicts.
   */
  async function checkAlreadyAssignedOnPublish(): Promise<
    Array<PublishScopeConflict>
  > {
    const plantId = Number(profileStore.userAttributes?.plant);
    if (!plantId) return [];

    const currentScopeList = templateStore.template.scopeList || [];
    if (currentScopeList.length === 0) return [];

    const activeScreenId = resolveActiveScreenId(
      templateStore.template.screens,
      currentScopeList,
    );
    const activeScopeType = resolveScopeType(activeScreenId);

    const selectedScopeIds = new Set(
      currentScopeList
        .filter(
          (scope) =>
            String(scope?.scopeType ?? '').toUpperCase() === activeScopeType,
        )
        .map((scope) => String(scope?.scopeValue ?? '').trim())
        .filter((id) => id.length > 0),
    );
    if (selectedScopeIds.size === 0) return [];

    const [templates, scopeLabels] = await Promise.all([
      getTemplatesByPlant(plantId),
      loadScopeLabels(activeScopeType),
    ]);

    const conflictsByScope = new Map<string, PublishScopeConflict>();
    for (const tpl of templates) {
      const isCurrentTemplate =
        String(tpl.id ?? '') === String(templateStore.template.id ?? '');
      const isPublished =
        String(tpl.status ?? '').toLowerCase() === 'published';
      const matchesScreen =
        resolveActiveScreenId(tpl.screens, tpl.scopeList) === activeScreenId;
      if (!isCurrentTemplate && isPublished && matchesScreen) {
        const tplScopeIds = (tpl.scopeList ?? [])
          .filter(
            (scope) =>
              String(scope?.scopeType ?? '').toUpperCase() === activeScopeType,
          )
          .map((scope) => String(scope?.scopeValue ?? '').trim())
          .filter((id) => id.length > 0);

        for (const id of tplScopeIds) {
          if (selectedScopeIds.has(id) && !conflictsByScope.has(id)) {
            conflictsByScope.set(id, {
              scopeLabel: scopeLabels.get(id) ?? id,
              scopeType: activeScopeType,
              scopeValue: id,
              templateLabel:
                String(tpl.label ?? '').trim() ||
                i18n.global.t('PAGE_BUILDER_ANOTHER_TEMPLATE'),
            });
          }
        }
      }
    }

    return [...conflictsByScope.values()];
  }

  return { checkAlreadyAssignedOnPublish };
}

