/**
 * @returns The translation keys for a given widget code, if available.
 * @param code The widget code to get translation keys for.
 */
function getWidgetTranslationKeys(code: string): {
  titleKey?: string;
  subtitleKey?: string;
} {
  switch (code) {
    case 'target': {
      return {
        titleKey: 'PAGE_BUILDER_TARGET',
        subtitleKey: 'PAGE_BUILDER_PLANNED_PRODUCTION_QUANTITY',
      };
    }
    case 'production': {
      return {
        titleKey: 'PAGE_BUILDER_PRODUCTION',
        subtitleKey: 'PAGE_BUILDER_ACTUAL_PRODUCTION_QUANTITY',
      };
    }
    case 'delta': {
      return {
        titleKey: 'PAGE_BUILDER_DELTA',
        subtitleKey: 'PAGE_BUILDER_DIFFERENCE_TARGET_PRODUCT',
      };
