/**
 * @returns The translated title and subtitle for a widget, based on its code and fallback values.
 * @param code The widget code to translate.
 * @param fallbackTitle The fallback title to use if no translation key is found.
 * @param fallbackSubtitle The fallback subtitle to use if no translation key is found.
 */
export function translateWidgetText(
  code: string,
  fallbackTitle: string,
  fallbackSubtitle: string,
): { title: string; subtitle: string } {
  const { titleKey, subtitleKey } = getWidgetTranslationKeys(code);
  return {
    title: titleKey ? i18n.global.t(titleKey) : fallbackTitle,
    subtitle: subtitleKey ? i18n.global.t(subtitleKey) : fallbackSubtitle,
  };
}

/**
 * Infers the number of columns from widget positions.
 * @param widgets The widgets to analyze.
 * @returns The inferred columns count.
 */
function inferColumnsCountFromWidgets(
  widgets: Array<{ position?: string }> | undefined,
): 1 | 2 | 3 {
  const positions = new Set(
    (widgets ?? []).map((w) => coerceLowerString(w.position)).filter(Boolean),
  );
  if (positions.has('middle')) return 3;
  if (positions.has('left') || positions.has('right')) return 2;
  return 1;
}

/**
 * Maps a widget position to a column index.
 * @param columnsCount The number of columns.
 * @param position The raw widget position.
 * @returns The 0-based column index.
 */
function positionToColumnIndex(
  columnsCount: 1 | 2 | 3,
  position: unknown,
): number {
  const p = coerceLowerString(position);
  if (columnsCount === 1) return 0;
  if (columnsCount === 2) return p === 'right' ? 1 : 0;
  if (p === 'right') return 2;
  if (p === 'middle') return 1;
  return 0;
}

/**
 * Derives a semantic widget position name from a column index.
 * @param columnsCount Total columns in the section.
 * @param columnIndex The current column index.
 * @returns The semantic position.
 */
function getSemanticWidgetPosition(
  columnsCount: number,
  columnIndex: number,
): 'left' | 'middle' | 'right' | 'full' {
  if (columnsCount <= 1) return 'full';
  if (columnsCount === 2) return columnIndex === 0 ? 'left' : 'right';
  if (columnIndex === 0) return 'left';
  if (columnIndex === columnsCount - 1) return 'right';
  return 'middle';
}

/**
 * Converts a column count into the component size expected by the backend.
 * @param columnsCount Total columns in the section.
 * @returns The component size.
 */
function getComponentSizeFromColumns(
  columnsCount: number,
): 'full' | 'half' | 'third' {
  if (columnsCount <= 1) return 'full';
  if (columnsCount === 2) return 'half';
  return 'third';
}

/**
 * Flattens section widgets into the backend widget DTO list.
 * @param section The section to flatten.
 * @param widgetApiLookup Lookup map of widget definitions.
 * @returns The flattened widgets list.
 */
export function flattenWidgets(
  section: Section,
  widgetApiLookup: Record<string, { widget: ComponentData }>,
): Array<WidgetDto> {
  const widgets: Array<WidgetDto> = [];
  const columns = Array.isArray(section.columns) ? section.columns : [];
  const columnsCount = columns.length;
  const componentSize = getComponentSizeFromColumns(columnsCount);
  let order = 0;
  for (const [columnIndex, col] of columns.entries()) {
    const placedWidgets = Array.isArray(col.widgets) ? col.widgets : [];
    for (const placed of placedWidgets) {
      const key = placed.defId;
      const component = widgetApiLookup[key]?.widget;
      widgets.push({
        component: {
          api: component?.apiLink ?? '',
          code: component?.code ?? '',
          configSchema: component?.configSchema ?? {},
          label: component?.label ?? '',
          showLabel: Boolean(component?.showLabel),
          size: componentSize,
        },
        configSchema: {},
        id: `widget_${order}`,
        label: placed.title || component?.label || '',
        order,
        position: getSemanticWidgetPosition(columnsCount, columnIndex),
      });
      order += 1;
    }
  }
  return widgets;
}

/**
 * Maps an API component DTO into the store shape.
 * @param component The API component to map.
 * @returns The mapped store component data.
 */
function mapApiComponent(component: ApiComponent): ComponentData {
  let configSchema: Record<string, unknown> = {};
  switch (component.code) {
    case 'target':
    case 'production': {
      configSchema = {
        container: { class: 'kpi-widget' },
        header: { class: 'kpi-header' },
        value: { class: 'kpi-value' },
      };
      break;
    }
    case 'delta': {
      configSchema = {
        container: { class: 'kpi-widget kpi-delta' },
        header: { class: 'kpi-header' },
        value: { class: 'kpi-value' },
      };
      break;
    }
    case 'event_timer': {
      configSchema = {
        container: { class: 'event-widget' },
        header: { class: 'event-header' },
        value: { class: 'event-value' },
      };
      break;
    }
    case 'reference_in_prod':
    case 'tool_in_prod': {
      configSchema = {
        container: { class: 'reference-widget' },
        header: { class: 'reference-header' },
        value: { class: 'reference-value' },
      };
      break;
    }
    case 'scrap':
    case 'rework': {
      configSchema = {
        container: { class: 'nonquality-widget' },
        header: { class: 'nonquality-header' },
        value: { class: 'nonquality-value' },
      };
      break;
    }
    case 'stoppage': {
      configSchema = {
        container: { class: 'stoppage-widget' },
        header: { class: 'stoppage-header' },
        value: { class: 'stoppage-value' },
      };
      break;
    }
    case 'downtime': {
      configSchema = {
        container: { class: 'downtime-widget' },
        header: { class: 'downtime-header' },
        value: { class: 'downtime-value' },
      };
      break;
    }
    default: {
      configSchema = {};
    }
  }

  const {
    description: baseDescription = '',
    label: baseLabel,
    size: baseSize,
  } = component;
  let description = baseDescription;
  let label = baseLabel;
  let size = baseSize;

  if (component.code === 'stoppage') {
    description = i18n.global.t('PAGE_BUILDER_DOWNTIME_PLANNED_STOPPAGES');
    label = i18n.global.t('PAGE_BUILDER_STOPPAGE');
    size = 'third';
  } else if (component.code === 'downtime') {
    description = i18n.global.t('PAGE_BUILDER_CURRENT_OR_LAST_DOWNTIME');
    label = i18n.global.t('PAGE_BUILDER_DOWNTIME');
    size = 'full';
  }

  return {
    apiLink: component.apiId?.url ?? '',
    apiMethod: '',
    apiParams: {},
    appListId: component.appsList ? component.appsList.split(',') : [],
    code: component.code,
    configSchema,
    description,
    id: component.componentId,
    label,
    scopeId: [],
    showLabel: component.showLabel,
    size,
    value: component.defaultValue,
  };
}

/**
 * Maps the API component list into the store component shape.
 * @param components The API components to map.
 * @returns The mapped component list.
 */
export function mapApiComponents(
  components: Array<ApiComponent>,
): Array<ComponentData> {
  return components.map((component) => mapApiComponent(component));
}

/**
 * Maps a TemplateDto to an array of Section objects.
 * @param dto The template DTO to map.
 * @returns The array of Section objects.
 */
function mapTemplateDtoToSections(dto: TemplateDto): Array<Section> {
  const layout = dto.devices?.desktop?.layout;
  const sectionDtos = Array.isArray(layout?.sections) ? layout.sections : [];
  const ordered = [...sectionDtos].sort(
    (a, b) => (a.order ?? 0) - (b.order ?? 0),
  );

  return ordered.map((sectionDto, index) => {
    const widgetDtos = Array.isArray(sectionDto.widgets)
      ? [...sectionDto.widgets]
      : [];
    widgetDtos.sort((a, b) => (a.order ?? 0) - (b.order ?? 0));

    const columnsCount = inferColumnsCountFromWidgets(widgetDtos);
    const columns: Array<Section['columns'][number]> = Array.from(
      { length: columnsCount },
      (_, colIndex) => ({
        id: `col_${colIndex}`,
        widgets: [],
      }),
    );

    for (const widgetDto of widgetDtos) {
      const colIndex = positionToColumnIndex(columnsCount, widgetDto.position);
      const safeIndex = Math.max(0, Math.min(columns.length - 1, colIndex));
      columns[safeIndex].widgets.push({
        defId: widgetDto.component?.code ?? '',
        instanceId: widgetDto.id ?? newId('widget'),
        subtitle: widgetDto.component?.label ?? '',
        title: widgetDto.label ?? widgetDto.component?.label ?? '',
      });
    }

    return {
      columns,
      configSchema: sectionDto.configSchema ?? {},
      id: sectionDto.id ?? `section_${index}`,
      label: coerceTrimmedString(sectionDto.label),
      maxWidget: sectionDto.maxWidget ?? 0,
      minWidget: sectionDto.minWidget ?? 0,
      order: sectionDto.order ?? index,
      sideGroupId: readSideGroupIdFromConfigSchema(sectionDto.configSchema),
      widgets: [],
    };
  });
}

/**
 * Maps a TemplateDto to a PageBuilderTemplate object.
 * @param dto The template DTO to map.
 * @returns The PageBuilderTemplate object.
 */
export function mapTemplateDtoToBuilderTemplate(
  dto: TemplateDto,
): PageBuilderTemplate {
  const desktopLayout = dto.devices?.desktop?.layout;
  const width =
    typeof desktopLayout?.width === 'number' ? desktopLayout.width : 788;
  const height =
    typeof desktopLayout?.height === 'number' ? desktopLayout.height : 929;

  return {
    createdAt: dto.createdAt ?? '',
    createdBy: dto.createdBy ?? '',
    default: Boolean(dto.default),
    devices: {
      desktop: {
        layout: {
          height,
          sections: mapTemplateDtoToSections(dto),
          width,
        },
        resolution: dto.devices?.desktop?.resolution ?? '1920*1080',
      },
      mobile: {
        layout: dto.devices?.mobile?.layout ?? {},
        resolution: dto.devices?.mobile?.resolution ?? '',
      },
      tablet: {
        layout: dto.devices?.tablet?.layout ?? {},
        resolution: dto.devices?.tablet?.resolution ?? '',
      },
    },
    id: dto.id,
    label: dto.label ?? '',
    plant: dto.plant ?? 0,
    scopeList: Array.isArray(dto.scopeList) ? dto.scopeList : [],
    screens: Array.isArray(dto.screens) ? dto.screens : [],
    status: coerceTemplateStatus(dto.status),
    updatedAt: dto.updatedAt ?? '',
    updatedBy: dto.updatedBy ?? '',
  };
}

/**
 * Builds a PageBuilderTemplate from a TemplateDto.
 * @param dto The template DTO to build from.
 * @returns The constructed PageBuilderTemplate.
 */
export function buildTemplateFromDto(dto: TemplateDto): PageBuilderTemplate {
  return mapTemplateDtoToBuilderTemplate(dto);
}

/**
 * Filters widget definitions by a search string.
 * @param widgetDefinitions The widget definitions to filter.
 * @param search The free-text search string.
 * @returns The filtered widget definitions.
 */
export function filterWidgetDefinitions(
  widgetDefinitions: Array<WidgetDefinition>,
  search: string,
): Array<WidgetDefinition> {
  const q = search.trim().toLowerCase();
  if (!q) return widgetDefinitions;
  return widgetDefinitions.filter((widget) =>
    `${widget.title} ${widget.subtitle}`.toLowerCase().includes(q),
  );
}

import { defineAsyncComponent, type Component } from 'vue';
import { useTemplateStore } from '../store/template-store';
import type { ComponentData } from './template-store-helpers';
import { i18n } from '@/localization/i18n';

/**
 * Gets the widget Vue component.
 * @param widgetDefinitionId The widget definition ID.
 * @returns The widget component.
 */
export function getWidgetComponent(widgetDefinitionId: string): Component {
  if (widgetDefinitionId === '__unused__') {
    // Intentionally ignored: widget component currently does not vary by ID.
  }
  return defineAsyncComponent(() => import('../components/widgets/widget.vue'));
}

// Helper to get widget size (1=full, 2=half, 3=not full)
/**
 * Gets the widget size.
 * @param widgetDefinitionId The widget definition ID.
 * @returns The widget size.
 */
export function getWidgetSize(widgetDefinitionId: string): number {
  const templateStore = useTemplateStore();
  const widget = templateStore.widgetApiMap[widgetDefinitionId]?.widget;
  if (widgetDefinitionId === 'downtime') {
    return 1;
  }
  if (widgetDefinitionId === 'stoppage') {
    return 3;
  }
  if (!widget) return 1;
  if (widget.size === 'full') return 1;
  if (widget.size === 'half') return 2;
  if (widget.size === 'not full') return 3;
  if (widget.size === 'third') return 3;
  if (widget.size === 'thirds') return 3;
  return 1;
}

// Helper to get widget config
/**
 * Gets the widget configuration for a widget definition.
 * @param widgetDefinitionId The widget definition ID.
 * @returns The widget configuration, if available.
 */
export function getWidgetConfig(
  widgetDefinitionId: string,
): ComponentData | undefined {
  const templateStore = useTemplateStore();
  return templateStore.widgetApiMap[widgetDefinitionId]?.widget;
}

/**
 * Checks if a widget can be placed in a given section/column, and returns a rule result.
 * @param widgetDefinitionId The widget definition ID.
 * @param section The target section object. Should have id and columns properties.
 * @param section.id The ID of the section.
 * @param section.columns The columns array of the section.
 * @param col The target column object. Should have id and widgets properties.
 * @param col.id The ID of the column.
 * @param col.widgets The widgets array of the column.
 * @param sectionRows The array of section rows (for row grouping).
 * @returns Rule result indicating if widget placement is allowed and an optional message.
 */
export function getWidgetPlacementRule(
  widgetDefinitionId: string,
  section: {
    id: string;
    columns: Array<{ id: string; widgets: Array<{ id: string }> }>;
  },
  col: { id: string; widgets: Array<{ id: string }> },
  sectionRows: Array<{ sections: Array<{ id: string }> }> = [], // The array of section rows for row grouping
): { allowed: boolean; message?: string } {
  // Returns rule result indicating if widget placement is allowed and an optional message
  if (!section || !col) {
    return {
      allowed: false,
      message: i18n.global.t('PAGE_BUILDER_INVALID_TARGET'),
    };
  }
  if (col.widgets.length > 0) {
    return {
      allowed: false,
      message: i18n.global.t('PAGE_BUILDER_COLUMN_ALREADY_HAS_WIDGET'),
    };
  }
  // Prevent adding the same widget more than once in the section (any column)
  const alreadyExists = section.columns.some((column) =>
    column.widgets.some((w) => w.id === widgetDefinitionId),
  );
  const widgetConfig = getWidgetConfig(widgetDefinitionId);
  const widgetLabel =
    widgetConfig?.label || i18n.global.t('PAGE_BUILDER_WIDGET');
  if (alreadyExists) {
    return {
      allowed: false,
      message: i18n.global.t('PAGE_BUILDER_DUPLICATE_WIDGET_IN_SECTION', {
        widgetLabel,
      }),
    };
  }
  const widgetSize = getWidgetSize(widgetDefinitionId);
  const columnsCount = Array.isArray(section.columns)
    ? section.columns.length
    : 0;
  const row = sectionRows.find(
    (r) =>
      Array.isArray(r.sections) && r.sections.some((s) => s.id === section.id),
  );
  const rowSectionsCount = row?.sections?.length ?? 1;
  if (widgetSize === 1) {
    if (rowSectionsCount !== 1 || columnsCount !== 1) {
      return {
        allowed: false,
        message: i18n.global.t(
          'PAGE_BUILDER_WIDGET_SINGLE_SECTION_SINGLE_COLUMN',
          {
            widgetLabel,
          },
        ),
      };
    }
  } else if (widgetSize === 2 && columnsCount === 3) {
    return {
      allowed: false,
      message: i18n.global.t('PAGE_BUILDER_WIDGET_ONE_OR_TWO_COLUMNS', {
        widgetLabel,
      }),
    };
  }
  return { allowed: true };
}

/**
 * Checks if a widget can be placed in a given section/column, and returns a rule result.
 * @param widgetDefinitionId The widget definition ID.
 * @param section The target section object.
 * @param col The target column object.
 * @param sectionRows The array of section rows for row grouping.
 * @returns Rule result indicating if widget placement is allowed and an optional message.
 */

