import axios, { AxiosResponse } from 'axios';
import {
  CreateRoutingDto,
  UpdateRoutingDto,
  CreateOperationDto,
  UpdateOperationDto,
  MaterialsResponse,
  OperationType,
  RoutingDto,
  Operation,
} from '../dto/routing.dto';
import { useProfileStore } from '@/store/user-auth-store';
import appLogger from '@/utils/logger/app-logger';

let token = import.meta.env.TOKEN;
token = token === 'PING_FEDERATE' ? sessionStorage.getItem('id_token') : token;
const adminUrl = import.meta.env.ADMIN_BACKEND_URL;
const getHeaders = (): Record<string, string> => ({
  authorization: `Bearer ${token}`,
});

class RoutingApiService {
  public static async findAll(): Promise<Array<RoutingDto>> {
    const userAttributesStore = useProfileStore();
    const plant = Number(userAttributesStore.userAttributes.plant);
    try {
      const response: AxiosResponse = await axios.get(
        `${adminUrl}/routings?plant=${plant}`,
        {
          headers: getHeaders(),
        },
      );
      return response.data;
    } catch (error) {
      appLogger.error(`Failed to fetch routings: ${String(error)}`);
      throw error;
    }
  }

  public static async findOne(id: number): Promise<RoutingDto> {
    const userAttributesStore = useProfileStore();
    const plant = Number(userAttributesStore.userAttributes.plant);
    try {
      const response: AxiosResponse = await axios.get(
        `${adminUrl}/routings/${id}?plant=${plant}`,
        {
          headers: getHeaders(),
        },
      );
      return response.data;
    } catch (error) {
      appLogger.error(`Failed to fetch routing ${id}: ${String(error)}`);
      throw error;
    }
  }

  public static async create(dto: CreateRoutingDto): Promise<RoutingDto> {
    try {
      const response: AxiosResponse = await axios.post(
        `${adminUrl}/routings`,
        dto,
        {
          headers: getHeaders(),
        },
      );
      return response.data;
    } catch (error) {
      appLogger.error(`Failed to create routing: ${String(error)}`);
      throw error;
    }
  }

  public static async update(
    id: number,
    dto: UpdateRoutingDto,
  ): Promise<RoutingDto> {
    try {
      const response: AxiosResponse = await axios.put(
        `${adminUrl}/routings/${id}`,
        dto,
        {
          headers: getHeaders(),
        },
      );
      return response.data;
    } catch (error) {
      appLogger.error(`Failed to update routing ${id}: ${String(error)}`);
      throw error;
    }
  }

  public static async listOperationTypes(): Promise<Array<OperationType>> {
    try {
      const response: AxiosResponse = await axios.get(
        `${adminUrl}/routings/operation-types`,
        {
          headers: getHeaders(),
        },
      );
      return response.data;
    } catch (error) {
      appLogger.error(`Failed to fetch operation types: ${String(error)}`);
      throw error;
    }
  }

  public static async listOperations(
    routingId: number,
  ): Promise<Array<Operation>> {
    try {
      const response: AxiosResponse = await axios.get(
        `${adminUrl}/routings/${routingId}/operations`,
        { headers: getHeaders() },
      );
      return response.data;
    } catch (error) {
      appLogger.error(
        `Failed to list operations for routing ${routingId}: ${String(error)}`,
      );
      throw error;
    }
  }

  public static async remove(id: number): Promise<void> {
    try {
      await axios.delete(`${adminUrl}/routings/${id}`, {
        headers: { authorization: `Bearer ${token}` },
      });
    } catch (error) {
      appLogger.error(`Failed to delete routing ${id}: ${String(error)}`);
      throw error;
    }
  }

  // Materials
  public static async assignMaterial(
    routingId: number,
    materialId: string,
    plant: number,
  ): Promise<void> {
    try {
      const response: AxiosResponse = await axios.post(
        `${adminUrl}/routings/${routingId}/materials`,
        { materialId, plant },
        { headers: getHeaders() },
      );
      return response.data;
    } catch (error) {
      appLogger.error(
        `Failed to assign material ${materialId} to routing ${routingId}: ${String(error)}`,
      );
      throw error;
    }
  }

  public static async unassignMaterial(
    routingId: number,
    materialId: string,
    plant: number,
  ): Promise<void> {
    try {
      await axios.put(
        `${adminUrl}/routings/${routingId}/materials/${encodeURIComponent(materialId)}?plant=${plant}`,
        {},
        { headers: getHeaders() },
      );
    } catch (error) {
      appLogger.error(
        `Failed to unassign material ${materialId} from routing ${routingId}: ${String(error)}`,
      );
      throw error;
    }
  }

  // Operations
  public static async listMaterials(
    routingId: number | undefined,
    plant: number,
  ): Promise<MaterialsResponse> {
    try {
      const url = routingId
        ? `${adminUrl}/routings/${routingId}/materials?plant=${encodeURIComponent(String(plant))}`
        : `${adminUrl}/admin/getAllMaterial/${encodeURIComponent(String(plant))}`;
      const response: AxiosResponse = await axios.get(url, {
        headers: getHeaders(),
      });
      return response.data;
    } catch (error) {
      appLogger.error(
        routingId
          ? `Failed to list materials for routing ${routingId}: ${String(error)}`
          : `Failed to list available materials: ${String(error)}`,
      );
      throw error;
    }
  }

  public static async getOperationById(
    routingId: number,
    operationId: number,
  ): Promise<Operation> {
    try {
      const response: AxiosResponse = await axios.get(
        `${adminUrl}/routings/${routingId}/operations/${operationId}`,
        { headers: getHeaders() },
      );
      return response.data;
    } catch (error) {
      appLogger.error(
        `Failed to get operation ${operationId}: ${String(error)}`,
      );
      throw error;
    }
  }

  public static async createOperation(
    dto: CreateOperationDto,
  ): Promise<Operation> {
    try {
      const response: AxiosResponse = await axios.post(
        `${adminUrl}/routings/${dto.routingId}/operations`,
        {
          operationName: dto.operationName,
          operationTypeId: dto.operationTypeId,
        },
        { headers: getHeaders() },
      );
      return response.data;
    } catch (error) {
      appLogger.error(
        `Failed to create operation for routing ${dto.routingId}: ${String(error)}`,
      );
      throw error;
    }
  }

  public static async updateOperation(
    routingId: number,
    opId: number,
    dto: UpdateOperationDto,
  ): Promise<Operation> {
    try {
      const response: AxiosResponse = await axios.put(
        `${adminUrl}/routings/${routingId}/operations/${opId}`,
        dto,
        { headers: getHeaders() },
      );
      return response.data;
    } catch (error) {
      appLogger.error(`Failed to update operation ${opId}: ${String(error)}`);
      throw error;
    }
  }

  public static async removeOperation(
    routingId: number,
    opId: number,
  ): Promise<void> {
    try {
      await axios.delete(
        `${adminUrl}/routings/${routingId}/operations/${opId}`,
        { headers: getHeaders() },
      );
    } catch (error) {
      appLogger.error(`Failed to delete operation ${opId}: ${String(error)}`);
      throw error;
    }
  }

  public static async reorderOperations(
    routingId: number,
    payload: { routingOperationIds: Array<number> },
  ): Promise<Array<Operation>> {
    try {
      const response: AxiosResponse = await axios.post(
        `${adminUrl}/routings/${routingId}/operations/reorder`,
        payload,
        { headers: getHeaders() },
      );
      return response.data;
    } catch (error) {
      appLogger.error(
        `Failed to reorder operations for routing ${routingId}: ${String(error)}`,
      );
      throw error;
    }
  }
}

