import { computed, type ComputedRef } from 'vue';
import { useProfileStore } from '@/store/user-auth-store';

export interface UserAction {
  object: string;
  actionType: string;
}

/**
 * Checks if the current user has permission for a specific action
 * @param actionName The name of the action to check permissions for
 * @returns boolean indicating if the user has permission
 */
export const isActionAllowed = (actionName: string): boolean => {
  const store = useProfileStore();
  const actions: Array<UserAction> =
    (store.userActions as Array<UserAction>) || [];

  const matchingActions = actions.filter(
    (action) => action.object?.toLowerCase() === actionName.toLowerCase(),
  );
  if (matchingActions.length === 0) {
    return true; // If action doesn't exist, enable
  }
  return matchingActions.some(
    (action) => action.actionType?.toLowerCase() === 'enable',
  );
};

/**
 * Helper to create permission-based computed properties
 * @param actionName The name of the action to check permissions for
 * @returns computed boolean indicating if the user has permission
 */
export const usePermission = (actionName: string): ComputedRef<boolean> => {
  return computed(() => isActionAllowed(actionName));
};

import { Plant } from '@/types/plant';
import { ProductionLine } from '@/types/prodline';
import { Resource } from '@/types/resource';
import { Uap } from '@/types/uap';
import { Workcenter } from '@/types/workcenter';

/**
 * Checks if a specific resource ID exists within the given plants array.
 * @param plants - The array of plant objects to search through.
 * @param resourceId - The resource ID to check for existence.
 * @returns - Returns true if the resource ID exists, otherwise false.
 */
// Recursive function to search for a resourceId in the plants hierarchy
export function checkResourceIdExists(
  plants: Array<Plant>,
  resourceId: string,
): boolean {
  // Helper function to recursively search each level
  const searchResources = (
    items: Array<Plant | Uap | ProductionLine | Workcenter | Resource>,
  ): boolean => {
    for (const item of items) {
      // Check if the current item has resources (Workcenter level)
      if ('children' in item && item.children) {
        // If it's a Workcenter, we look for Resource within the children
        if ('value' in item && (item as Workcenter).children) {
          const resourceIds = (item as Workcenter).children.map(
            (resource) => resource.value,
          );
          if (resourceIds.includes(resourceId)) return true;
        }

        // If it's a UAP or ProductionLine, recurse into the children
        if ('children' in item && searchResources(item.children)) {
          return true;
        }
      }
    }
    return false;
  };
  return searchResources(plants);
}

